-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Arturo Fuente' hote, 'celebrities' champ
        UNION ALL SELECT 'Arturo Fuente' hote, 'gamme' champ
        UNION ALL SELECT 'Arturo Fuente' hote, 'history' champ
        UNION ALL SELECT 'Arturo Fuente' hote, 'pairings' champ
        UNION ALL SELECT 'Padrón' hote, 'celebrities' champ
        UNION ALL SELECT 'Padrón' hote, 'gamme' champ
        UNION ALL SELECT 'Padrón' hote, 'history' champ
        UNION ALL SELECT 'Padrón' hote, 'pairings' champ
        UNION ALL SELECT 'Cohiba' hote, 'celebrities' champ
        UNION ALL SELECT 'Cohiba' hote, 'gamme' champ
        UNION ALL SELECT 'Cohiba' hote, 'history' champ
        UNION ALL SELECT 'Cohiba' hote, 'pairings' champ
        UNION ALL SELECT 'Cohiba USA' hote, 'celebrities' champ
        UNION ALL SELECT 'Cohiba USA' hote, 'gamme' champ
        UNION ALL SELECT 'Cohiba USA' hote, 'history' champ
        UNION ALL SELECT 'Cohiba USA' hote, 'pairings' champ
        UNION ALL SELECT 'Davidoff' hote, 'celebrities' champ
        UNION ALL SELECT 'Davidoff' hote, 'gamme' champ
        UNION ALL SELECT 'Davidoff' hote, 'history' champ
        UNION ALL SELECT 'Davidoff' hote, 'pairings' champ
        UNION ALL SELECT 'Oettinger Davidoff' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

