-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Arturo Fuente' AS hote, 'fr' AS lang, 'limited_eds : Fuente Fuente OpusX Angel''s Share' AS quoi, (JSON_CONTAINS(`limited_eds`, '"Fuente Fuente OpusX Angel''s Share"')) AS ok FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'limited_eds : Fuente Fuente OpusX Serie Heaven and Earth BBMF', (JSON_CONTAINS(`limited_eds`, '"Fuente Fuente OpusX Serie Heaven and Earth BBMF"')) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1912 — West Tampa, Floride' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Né à Güines, à Cuba, le 18 novembre 1887, Arturo Fuente Sr. s''installe à Key West en 1906, puis à West Tampa en 1910, d''après arturofuente.com ; Wikipédia date de son côté son arrivée aux États-Unis de 1902. Il fonde en 1912, à vingt-quatre ans, A. Fuente & Company au 813 Francis Street, à West Tampa. En 1924, la manufacture brûle pendant qu''il est à Cuba pour acheter du tabac ; il passe les vingt-deux années suivantes comme directeur général d''une entreprise locale.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Arturo Fuente Sr. débarqua à Tampa en 1902, parmi des milliers de torcedores cubains qui avaient suivi la migration de l''industrie du cigare vers la Floride. En 1912, il fonda sa manufacture sur un principe qui allait définir la famille pendant quatre générations : chaque cigare qui sortait de l''atelier devait être un cigare qu''il était fier d''avoir roulé lui-même. La maison grandit lentement, délibérément, sans les capitaux des grandes structures — elle grandit parce que ses cigares valaient régulièrement mieux que leur prix.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Born in Güines, Cuba, on 18 November 1887, Arturo Fuente Sr. settles in Key West in 1906, then in West Tampa in 1910, according to arturofuente.com; Wikipedia, for its part, dates his arrival in the United States to 1902. In 1912, aged twenty-four, he founds A. Fuente & Company at 813 Francis Street, West Tampa. In 1924, the factory burns down while he is in Cuba buying tobacco; he spends the following twenty-two years as general manager of a local company.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Arturo Fuente Sr. arrived in Tampa in 1902, one of thousands of Cuban torcedores who had followed the cigar industry''s migration to Florida. In 1912, he founded his factory with one principle that would define the family for four generations: every cigar that left the building had to be something he was proud to have made himself. The factory grew slowly, deliberately, without the capital investment of the larger corporate houses. It grew because its cigars were consistently better than their price suggested.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Nacido en Güines, Cuba, el 18 de noviembre de 1887, Arturo Fuente Sr. se instala en Key West en 1906 y después en West Tampa en 1910, según arturofuente.com; Wikipedia, por su parte, fecha su llegada a Estados Unidos en 1902. En 1912, a los veinticuatro años, funda A. Fuente & Company en el 813 de Francis Street, en West Tampa. En 1924, la manufactura se incendia mientras él está en Cuba comprando tabaco; pasa los veintidós años siguientes como director general de una empresa local.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Arturo Fuente Sr. desembarcó en Tampa en 1902, entre miles de torcedores cubanos que habían seguido la migración de la industria del puro hacia Florida. En 1912 fundó su manufactura sobre un principio que iba a definir a la familia durante cuatro generaciones: cada puro que saliera del taller debía ser un puro que él estuviera orgulloso de haber liado él mismo. La casa creció despacio, deliberadamente, sin los capitales de las grandes estructuras —creció porque sus puros valían con regularidad más que su precio.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Geboren am 18. November 1887 in Güines auf Kuba, lässt sich Arturo Fuente Sr. 1906 in Key West nieder, dann 1910 in West Tampa, laut arturofuente.com; Wikipedia datiert seine Ankunft in den Vereinigten Staaten dagegen auf 1902. 1912 gründet er mit vierundzwanzig Jahren A. Fuente & Company in der Francis Street 813 in West Tampa. 1924 brennt die Manufaktur ab, während er auf Kuba Tabak einkauft; die folgenden zweiundzwanzig Jahre verbringt er als Generaldirektor eines örtlichen Unternehmens.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Arturo Fuente Sr. ging 1902 in Tampa an Land, unter Tausenden kubanischer Torcedores, die der Wanderung der Zigarrenindustrie nach Florida gefolgt waren. 1912 gründete er seine Manufaktur auf einem Grundsatz, der die Familie über vier Generationen bestimmen sollte: Jede Zigarre, die die Werkstatt verließ, musste eine sein, auf die er stolz gewesen wäre, hätte er sie selbst gerollt. Das Haus wuchs langsam, mit Bedacht, ohne das Kapital der großen Gebilde — es wuchs, weil seine Zigarren regelmäßig mehr wert waren als ihr Preis.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('1887年11月18日生于古巴吉内斯的老阿图罗·富恩特，据 arturofuente.com，1906年定居基韦斯特，1910年又迁至西坦帕；维基百科则把他抵达美国的时间定在1902年。1912年，二十四岁的他在西坦帕的弗朗西斯街813号创办了 A. Fuente & Company。1924年，他赴古巴采购烟草期间，工厂毁于火灾；此后二十二年，他担任一家本地企业的总经理。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1902年，阿图罗·富恩特登上坦帕的码头，与成千上万随雪茄业迁往佛罗里达的古巴卷制师同行。1912年，他以一条日后定义了这个家族四代人的原则创办工厂：凡是走出作坊的雪茄，都必须是他自己卷了也会引以为豪的雪茄。这家字号长得慢，也长得有意为之，没有大机构的资本——它之所以长起来，是因为它的雪茄价值稳定地高过它的价格。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('وُلد أرتورو فوينتي الأب في غوينيس بكوبا في 18 نوفمبر 1887، واستقرّ في كي ويست عام 1906، ثم في ويست تامبا عام 1910، بحسب arturofuente.com؛ أما ويكيبيديا فتؤرّخ وصوله إلى الولايات المتحدة بعام 1902. وفي 1912، وهو في الرابعة والعشرين من عمره، أسّس A. Fuente & Company في 813 شارع فرانسيس في ويست تامبا. وفي 1924 احترق المصنع بينما كان في كوبا لشراء التبغ؛ وقضى بعد ذلك اثنتين وعشرين سنة مديرًا عامًا لشركة محلية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('نزل أرتورو فوينتي الأب في تامبا عام 1902، بين آلاف اللافّين الكوبيين الذين تبعوا هجرة صناعة السيجار إلى فلوريدا. وفي 1912 أسّس مصنعه على مبدأ سيحدّد العائلة أربعة أجيال: كل سيجار يخرج من الورشة يجب أن يكون سيجارًا يفخر بأنه لفّه بنفسه. نمت الدار ببطء وعن قصد، بلا رساميل الكيانات الكبرى — نمت لأن سيجارها كان يساوي بانتظام أكثر من سعره.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Son fils Carlos Fuente Sr., né en 1935, devient seul propriétaire de l''entreprise en 1956, en rachetant pour un dollar la part de son frère aîné Arturo Oscar ; Arturo Sr., retraité, meurt en 1973. Au début des années 1970, Carlos achète une manufacture au Nicaragua ; selon son fils, le premier Don Carlos vendu, en 1976, a été roulé à Estelí. En 1978, la rébellion sandiniste brûle l''usine nicaraguayenne ; en 1979, un incendie « accidentel » détruit celle du Honduras.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Carlos Fuente Sr. hérita de l''affaire à la mort de son père et la conduisit à travers l''expansion du marché premium américain du milieu du siècle. En 1980, un incendie détruisit entièrement la manufacture d''Ybor City. Chaque machine, chaque tabac en vieillissement, chaque archive de production : tout. La perte fut totale. Carlos avait la cinquantaine ; son fils Carlos Jr., que le métier appelle simplement Carlito, la vingtaine.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('His son Carlos Fuente Sr., born in 1935, becomes sole owner of the company in 1956, buying out the share of his elder brother Arturo Oscar for one dollar; Arturo Sr., retired, dies in 1973. In the early 1970s, Carlos buys a factory in Nicaragua; according to his son, the first Don Carlos sold, in 1976, was rolled in Estelí. In 1978, the Sandinista rebellion burns down the Nicaraguan factory; in 1979, an ‘accidental’ fire destroys the one in Honduras.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Carlos Fuente Sr. inherited the business after his father''s death and guided it through the mid-century expansion of the American premium market. In 1980, a fire destroyed the Ybor City factory entirely. Every piece of equipment, every aging tobacco, every production record — gone. The loss was absolute. Carlos was in his fifties. His son Carlos Jr., known within the industry simply as Carlito, was in his twenties.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Su hijo Carlos Fuente Sr., nacido en 1935, se convierte en único propietario de la empresa en 1956 al comprar por un dólar la parte de su hermano mayor Arturo Oscar; Arturo Sr., jubilado, muere en 1973. A comienzos de los años setenta, Carlos compra una manufactura en Nicaragua; según su hijo, el primer Don Carlos vendido, en 1976, fue liado en Estelí. En 1978, la rebelión sandinista incendia la fábrica nicaragüense; en 1979, un incendio «accidental» destruye la de Honduras.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Carlos Fuente Sr. heredó el negocio a la muerte de su padre y lo condujo a través de la expansión del mercado premium estadounidense de mediados de siglo. En 1980, un incendio destruyó enteramente la manufactura de Ybor City. Cada máquina, cada tabaco en envejecimiento, cada archivo de producción: todo. La pérdida fue total. Carlos tenía cincuenta y tantos años; su hijo Carlos Jr., a quien el oficio llama simplemente Carlito, veintitantos.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Sein Sohn Carlos Fuente Sr., 1935 geboren, wird 1956 alleiniger Inhaber des Unternehmens, indem er für einen Dollar den Anteil seines älteren Bruders Arturo Oscar kauft; Arturo Sr., im Ruhestand, stirbt 1973. Anfang der 1970er-Jahre kauft Carlos eine Manufaktur in Nicaragua; laut seinem Sohn wurde die erste verkaufte Don Carlos, 1976, in Estelí gerollt. 1978 setzt die sandinistische Rebellion die nicaraguanische Fabrik in Brand; 1979 zerstört ein „zufälliger“ Brand die in Honduras.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Carlos Fuente Sr. erbte das Geschäft beim Tod seines Vaters und führte es durch die Ausweitung des amerikanischen Premiummarkts der Jahrhundertmitte. 1980 zerstörte ein Brand die Manufaktur in Ybor City vollständig. Jede Maschine, jeder reifende Tabak, jede Produktionsakte: alles. Der Verlust war ganz. Carlos war in den Fünfzigern; sein Sohn Carlos Jr., den das Fach schlicht Carlito nennt, in den Zwanzigern.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('他的儿子老卡洛斯·富恩特生于1935年，1956年以一美元买下兄长阿图罗·奥斯卡的股份，成为公司唯一的所有者；已退休的老阿图罗于1973年去世。七十年代初，卡洛斯在尼加拉瓜买下一家工厂；据他的儿子所述，1976年售出的首支 Don Carlos 是在埃斯特利卷制的。1978年，桑地诺叛乱烧毁了尼加拉瓜的工厂；1979年，一场“意外”火灾毁掉了洪都拉斯的工厂。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('父亲去世后，卡洛斯·富恩特继承了生意，带着它穿过世纪中叶美国高端市场的扩张。1980年，一场大火把伊博城的工厂彻底烧毁。每一台机器、每一批正在陈化的烟叶、每一份生产档案：全部。损失是彻底的。那时卡洛斯五十多岁，他的儿子小卡洛斯——行内直接叫他卡利托——二十几岁。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وابنه كارلوس فوينتي الأب، المولود عام 1935، صار عام 1956 المالك الوحيد للشركة بشرائه مقابل دولار واحد حصة أخيه الذي يكبره سنًّا، أرتورو أوسكار؛ وتوفي أرتورو الأب، وهو متقاعد، عام 1973. وفي مطلع السبعينيات اشترى كارلوس مصنعًا في نيكاراغوا؛ وبحسب ابنه، فإن أول سيجار Don Carlos بيع، عام 1976، لُفّ في إستيلي. وفي 1978 أحرق التمرد الساندينيستي المصنع النيكاراغوي؛ وفي 1979 دمّر حريق «عرضي» مصنع هندوراس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('ورث كارلوس فوينتي الأب العمل عند وفاة أبيه، وقاده عبر توسّع السوق الأمريكية الفاخرة في منتصف القرن. وفي 1980، دمّر حريق مصنع إيبور سيتي بالكامل. كل آلة، وكل تبغ في التعتيق، وكل أرشيف إنتاج: كل شيء. كانت الخسارة تامّة. كان كارلوس في الخمسينيات من عمره؛ وابنه كارلوس الابن، الذي تسمّيه المهنة ببساطة كارليتو، في العشرينيات.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Carlos Sr. continue de produire des cigares depuis le site d''Ybor City, dit arturofuente.com. Le 4 septembre 1980, Carlos Sr. et son fils Carlos Jr., dit Carlito, ouvrent Fuente Ltd à Santiago de los Caballeros, en République dominicaine. Le site d''Ybor City, sur 22nd Street, ne reste ouvert que comme centre de distribution : on n''y roule plus de cigares à la main.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La reconstruction les mena en République dominicaine, où la famille négocia l''accès à des terres de la vallée du Cibao. Ils se mirent à cultiver eux-mêmes — non plus acheter la feuille à des courtiers, mais contrôler chaque étape, de la plantation à la fermentation puis au roulage. Le Château de la Fuente, une plantation dont l''emplacement exact n''est communiqué à personne hors de la famille, devint la matière première des plus hautes ambitions de la maison. À la fin des années 1980, d''autres maisons envoyaient leurs assembleurs les plus expérimentés observer ce que faisaient les Fuente.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Carlos Sr. goes on producing cigars from the Ybor City site, says arturofuente.com. On 4 September 1980, Carlos Sr. and his son Carlos Jr., known as Carlito, open Fuente Ltd in Santiago de los Caballeros, in the Dominican Republic. The Ybor City site, on 22nd Street, stays open only as a distribution centre: cigars are no longer rolled there by hand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The rebuilding decision led to the Dominican Republic, where the Fuente family negotiated access to land in the Cibao Valley. They began growing tobacco themselves — not buying leaf from brokers, but controlling every stage of production from planting through fermentation through rolling. The Château de la Fuente, a plantation whose exact location is shared with no one outside the family, became the source material for the house''s highest aspirations. By the late 1980s, other houses sent their most experienced blenders to study what the Fuentes were doing.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Carlos Sr. sigue produciendo puros desde el sitio de Ybor City, dice arturofuente.com. El 4 de septiembre de 1980, Carlos Sr. y su hijo Carlos Jr., conocido como Carlito, abren Fuente Ltd en Santiago de los Caballeros, en República Dominicana. El sitio de Ybor City, en 22nd Street, solo permanece abierto como centro de distribución: allí ya no se lían puros a mano.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La reconstrucción los llevó a República Dominicana, donde la familia negoció el acceso a tierras del valle del Cibao. Se pusieron a cultivar ellos mismos —ya no comprar la hoja a corredores, sino controlar cada etapa, de la plantación a la fermentación y después al liado. El Château de la Fuente, una plantación cuya ubicación exacta no se comunica a nadie fuera de la familia, se convirtió en la materia prima de las más altas ambiciones de la casa. A finales de los años ochenta, otras casas enviaban a sus ligadores más experimentados a observar lo que hacían los Fuente.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Carlos Sr. stellt laut arturofuente.com weiterhin Zigarren am Standort Ybor City her. Am 4. September 1980 eröffnen Carlos Sr. und sein Sohn Carlos Jr., genannt Carlito, Fuente Ltd in Santiago de los Caballeros in der Dominikanischen Republik. Der Standort Ybor City an der 22nd Street bleibt nur als Vertriebszentrum geöffnet: Zigarren werden dort nicht mehr von Hand gerollt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Der Wiederaufbau führte sie in die Dominikanische Republik, wo die Familie den Zugang zu Land im Cibao-Tal aushandelte. Sie begannen selbst anzubauen — nicht mehr das Blatt von Maklern zu kaufen, sondern jede Stufe zu beherrschen, von der Pflanzung über die Fermentation bis zum Rollen. Das Château de la Fuente, eine Plantage, deren genaue Lage niemandem außerhalb der Familie mitgeteilt wird, wurde zum Rohstoff der höchsten Ansprüche des Hauses. Ende der achtziger Jahre schickten andere Häuser ihre erfahrensten Mischer, um zu beobachten, was die Fuentes taten.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('据 arturofuente.com，老卡洛斯仍在伊博城的厂址继续生产雪茄。1980年9月4日，老卡洛斯与儿子小卡洛斯（人称卡利托）在多米尼加共和国的圣地亚哥-德洛斯卡瓦列罗斯开设了 Fuente Ltd。伊博城厂址位于 22nd Street，仅作为配送中心保持开放：那里不再手工卷制雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('重建把他们带到了多米尼加共和国，家族在那里谈下了西瓦奥山谷的土地。他们开始自己种植——不再向中间商买叶子，而是掌控从种植到发酵再到卷制的每一步。富恩特庄园，一处确切位置从不向家族之外任何人透露的种植园，成了这家字号最高追求的原料来源。到八十年代末，别的字号会派最有经验的调配师前来观察富恩特家在做什么。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('واصل كارلوس الأب إنتاج السيجار من موقع إيبور سيتي، بحسب arturofuente.com. وفي 4 سبتمبر 1980 افتتح كارلوس الأب وابنه كارلوس الابن، المعروف بكارليتو، شركة Fuente Ltd في سانتياغو دي لوس كاباليروس بالجمهورية الدومينيكية. ولا يزال موقع إيبور سيتي في 22nd Street مفتوحًا، لكن كمركز توزيع فحسب: فلا يُلفّ فيه سيجار باليد بعد الآن.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('قادهم إعادة البناء إلى الجمهورية الدومينيكية، حيث تفاوضت العائلة على أراضٍ في وادي سيباو. وشرعوا يزرعون بأنفسهم — لا أن يشتروا الورقة من وسطاء، بل أن يضبطوا كل مرحلة، من الغرس إلى التخمير ثم اللفّ. وصار «شاتو دي لا فوينتي»، وهو مزرعة لا يُبلَّغ بموقعها الدقيق أحدٌ خارج العائلة، مادةَ أعلى طموحات الدار. وفي أواخر الثمانينيات، صارت دور أخرى ترسل أمهر خلّاطيها ليروا ما يفعله آل فوينتي.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Carlito crée en 1992 ce que la maison appelle le premier puro 100 % dominicain réussi, cape comprise, le Fuente Fuente OpusX, mis en vente le 18 novembre 1995, d''après arturofuente.com, qui rappelle que les sols dominicains étaient jugés impropres au tabac de cape. La cape pousse au Château de la Fuente, dans la région montagneuse de Bonao, à environ une heure au sud-est de Santiago : la famille y a planté ses premières graines au début des années 1990, et la ferme s''ouvre aux visiteurs du festival ProCigar.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('En 1995, Carlito lança l''Opus X. L''idée était simple et radicale : un cigare entièrement dominicain, cape comprise. On tenait alors la cape dominicaine pour trop fragile, trop fine, trop encline à se rompre pour tenir au niveau premium. Carlito passa des années à sélectionner et à travailler par la fermentation des feuilles dominicaines capables de supporter les contraintes du roulage. Il en sortit une cape sombre, huileuse, résistante, d''une complexité aromatique remarquable — et une liste d''attente qui dure encore trente ans plus tard.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('In 1992, Carlito creates what the house calls the first successful 100 per cent Dominican puro, wrapper included, the Fuente Fuente OpusX, put on sale on 18 November 1995, according to arturofuente.com, which points out that Dominican soils were judged unfit for wrapper tobacco. The wrapper grows at Chateau de la Fuente, in the mountainous Bonao region, about an hour south-east of Santiago: the family planted its first seeds there in the early 1990s, and the farm opens to visitors of the ProCigar festival.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('In 1995, Carlito launched the Opus X. The concept was straightforward and radical: a cigar made entirely from Dominican tobacco, including the wrapper. Dominican wrapper had been dismissed as too fragile, too thin, too prone to breaking to function at the premium level. Carlito spent years selecting and fermentation-developing specific Dominican leaves that could withstand the demands of rolling. The result was a dark, oily, resilient wrapper of extraordinary aromatic complexity — and the Opus X, in a Double Corona format, created a waiting list that persists thirty years later.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Carlito crea en 1992 lo que la casa llama el primer puro 100 % dominicano logrado, capa incluida, el Fuente Fuente OpusX, puesto a la venta el 18 de noviembre de 1995, según arturofuente.com, que recuerda que los suelos dominicanos se consideraban impropios para el tabaco de capa. La capa crece en el Château de la Fuente, en la región montañosa de Bonao, a una hora aproximadamente al sureste de Santiago: la familia plantó allí sus primeras semillas a comienzos de los años noventa, y la finca se abre a los visitantes del festival ProCigar.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('En 1995, Carlito lanzó el Opus X. La idea era simple y radical: un puro enteramente dominicano, capa incluida. Se tenía entonces la capa dominicana por demasiado frágil, demasiado fina, demasiado propensa a romperse para sostenerse al nivel premium. Carlito pasó años seleccionando y trabajando por la fermentación hojas dominicanas capaces de soportar las tensiones del liado. De ahí salió una capa oscura, aceitosa, resistente, de una complejidad aromática notable —y una lista de espera que dura todavía treinta años después.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Carlito schafft 1992, was das Haus die erste gelungene Puro-Zigarre, zu 100 % dominikanisch nennt, Deckblatt eingeschlossen: die Fuente Fuente OpusX, laut arturofuente.com am 18. November 1995 in den Verkauf gebracht; die Seite erinnert daran, dass dominikanische Böden als ungeeignet für Deckblatttabak galten. Das Deckblatt wächst auf dem Château de la Fuente in der Bergregion von Bonao, etwa eine Stunde südöstlich von Santiago: Die Familie hat dort Anfang der 1990er-Jahre ihre ersten Samen gepflanzt, und die Farm steht den Besuchern des ProCigar-Festivals offen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('1995 brachte Carlito die Opus X heraus. Der Gedanke war einfach und radikal: eine ganz und gar dominikanische Zigarre, Deckblatt eingeschlossen. Das dominikanische Deckblatt galt damals als zu zerbrechlich, zu dünn, zu leicht reißend, um dem Premiumniveau standzuhalten. Carlito verbrachte Jahre damit, dominikanische Blätter auszuwählen und durch Fermentation so weit zu bringen, dass sie den Beanspruchungen des Rollens gewachsen waren. Daraus entstand ein dunkles, öliges, widerstandsfähiges Deckblatt von bemerkenswerter aromatischer Vielschichtigkeit — und eine Warteliste, die dreißig Jahre später noch besteht.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('卡利托于1992年创制出这家字号所称的首支成功的百分之百多米尼加 puro 雪茄，连茄衣在内，即 Fuente Fuente OpusX，据 arturofuente.com，该雪茄于1995年11月18日上市；该网站还提及，多米尼加的土壤曾被认为不适合种植茄衣烟叶。茄衣产自 Château de la Fuente，它位于多山的博瑙地区，在圣地亚哥东南约一小时路程处：家族于九十年代初在那里播下了首批种子，农场向 ProCigar 节的参观者开放。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('1995年，卡利托推出了 Opus X。想法简单而激进：一支彻头彻尾的多米尼加雪茄，连茄衣也是。当时人们认为多米尼加茄衣太脆、太薄、太容易破，撑不起高端水准。卡利托花了数年挑选叶子，并通过发酵把多米尼加叶子调到能承受卷制的张力。由此得到一张深色、油润、结实、香气复杂得惊人的茄衣——以及一份三十年后仍未消失的等货名单。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('ابتكر كارليتو عام 1992 ما تسمّيه الدار أول سيجار puro ناجح دومينيكي بنسبة 100%، بغلافه أيضًا، وهو Fuente Fuente OpusX الذي طُرح للبيع في 18 نوفمبر 1995، بحسب arturofuente.com؛ ويذكّر هذا الموقع بأن التربة الدومينيكية كانت تُعدّ غير صالحة لتبغ الغلاف. وينمو الغلاف في Château de la Fuente، في المنطقة الجبلية من بوناو، على بعد نحو ساعة إلى الجنوب الشرقي من سانتياغو: فقد غرست العائلة فيها أولى بذورها في مطلع التسعينيات، وتفتح المزرعة أبوابها لزوار مهرجان ProCigar.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('وفي 1995 أطلق كارليتو «أوبوس إكس». كانت الفكرة بسيطة وجذرية: سيجار دومينيكي بالكامل، بغلافه أيضًا. كان الغلاف الدومينيكي يُعدّ حينها هشًّا أكثر مما ينبغي، ورقيقًا، وسريع التمزّق، بحيث لا يصمد عند المستوى الفاخر. فأمضى كارليتو سنوات في انتقاء أوراق دومينيكية وتهيئتها بالتخمير حتى تحتمل إجهاد اللفّ. وخرج من ذلك غلاف داكن زيتي متين، ذو تركيب عطري لافت — وقائمة انتظار ما زالت قائمة بعد ثلاثين عامًا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Carlos Fuente Sr. meurt en août 2016, à 81 ans. Carlito présidait alors l''entreprise ; sa sœur Cynthia Fuente-Suarez, vice-présidente selon arturofuente.com, et lui sont les petits-enfants du fondateur. La maison note que, quatre générations après les débuts, l''entreprise reste familiale ; le livre Arturo Fuente: Since 1912 évoque une quatrième génération qui attend dans les coulisses.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('La famille exploite aujourd''hui la plus grande manufacture de cigares indépendante de République dominicaine : le Château de la Fuente alimente les gammes hautes, et l''usine principale produit un catalogue de plus de vingt gammes. Cynthia, fille de Carlito, représente la quatrième génération aux commandes.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Carlos Fuente Sr. dies in August 2016, aged 81. Carlito was then president of the company; his sister Cynthia Fuente-Suarez, vice-president according to arturofuente.com, and he are the founder''s grandchildren. The house notes that, four generations after the beginnings, the company remains a family business; the book Arturo Fuente: Since 1912 mentions a fourth generation waiting in the wings.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('The family now operates the largest independent cigar manufacturing operation in the Dominican Republic, with Chateau de la Fuente supplying the premium lines and the main factory producing across a catalog of over twenty ranges. Carlito''s daughter Cynthia represents the fourth generation in active management.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Carlos Fuente Sr. muere en agosto de 2016, a los 81 años. Carlito presidía entonces la empresa; su hermana Cynthia Fuente-Suarez, vicepresidenta según arturofuente.com, y él son los nietos del fundador. La casa señala que, cuatro generaciones después de los comienzos, la empresa sigue siendo familiar; el libro Arturo Fuente: Since 1912 evoca una cuarta generación que espera entre bastidores.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('La familia explota hoy la mayor manufactura de puros independiente de República Dominicana: el Château de la Fuente alimenta las gamas altas, y la fábrica principal produce un catálogo de más de veinte gamas. Cynthia, hija de Carlito, representa la cuarta generación al mando.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('Carlos Fuente Sr. stirbt im August 2016 im Alter von 81 Jahren. Carlito stand dem Unternehmen damals als Präsident vor; seine Schwester Cynthia Fuente-Suarez, laut arturofuente.com Vizepräsidentin, und er sind die Enkel des Gründers. Das Haus hält fest, dass das Unternehmen vier Generationen nach den Anfängen ein Familienbetrieb bleibt; das Buch Arturo Fuente: Since 1912 spricht von einer vierten Generation, die hinter den Kulissen wartet.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Die Familie betreibt heute die größte unabhängige Zigarrenmanufaktur der Dominikanischen Republik: Das Château de la Fuente versorgt die hohen Linien, und das Hauptwerk erzeugt einen Katalog von mehr als zwanzig Linien. Cynthia, Carlitos Tochter, steht für die vierte Generation an der Spitze.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('老卡洛斯·富恩特于2016年8月去世，享年81岁。当时卡利托担任公司总裁；他的姐妹辛西娅·富恩特-苏亚雷斯（据 arturofuente.com 为副总裁）与他同为创始人的孙辈。这家字号指出，在创业四代之后，企业依然是家族企业；《Arturo Fuente: Since 1912》一书提到，有第四代正在幕后等待。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
