UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('وتوفي كارلوس فوينتي الأب في أغسطس 2016 عن 81 عامًا. وكان كارليتو يرأس الشركة آنذاك؛ وهو وأخته سينثيا فوينتي-سواريز، نائبة الرئيس بحسب arturofuente.com، حفيدا المؤسّس. وتشير الدار إلى أنّ الشركة، بعد أربعة أجيال على البدايات، ما زالت عائلية؛ ويتحدث كتاب Arturo Fuente: Since 1912 عن جيل رابع ينتظر في الكواليس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
UNION ALL SELECT 'Arturo Fuente', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وتدير العائلة اليوم أكبر مصنع سيجار مستقلّ في الجمهورية الدومينيكية: «شاتو دي لا فوينتي» يغذّي التشكيلات العليا، والمصنع الرئيس ينتج كتالوغًا يضمّ أكثر من عشرين تشكيلة. وتمثّل سينثيا، ابنة كارليتو، الجيل الرابع في القيادة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente'
