UNION ALL SELECT 'Arturo Fuente', 'fr', 'celebrities 0', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`celebrities`, '$[0].anecdote')) AS BINARY) = CAST('Né en 1935, il devient seul propriétaire de la maison en 1956 et ouvre avec son fils, le 4 septembre 1980, Fuente Ltd à Santiago, en République dominicaine, après les incendies des usines du Nicaragua (1978) et du Honduras (1979), dit arturofuente.com. Il est mort en août 2016, à 81 ans ; la gamme Don Carlos porte son nom.' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente'
