UNION ALL SELECT 'Padrón', 'fr', 'source (correction)', (LOCATE(CAST('padron.com « José O. Padrón » (https://padron.com/jose-o-padron/, lue en octobre 2026 : départ de La Havane en avril 1961, Miami en février 1962, 600 dollars, Padrón Cigars ouverte en septembre 1964, Estelí, 1967, « bombing attempts by a small group of local extortionists ») ; padron.com « Dámaso Series » (lue en octobre 2026 : premier Padrón arrivé à Cuba des Canaries à la fin des années 1800, cape Connecticut d''Équateur, mild à medium, formats) ; padron.com « Padrón 1964 Anniversary Series » (lue en octobre 2026 : introduite en 1994 pour les 30 ans, tabac vieilli quatre ans, Exclusivo 50 x 5½) ; padron.com « Padrón 1926 Serie » (lue en octobre 2026 : sortie en 2002 pour les 75 ans de José O. Padrón, tabac vieilli cinq ans, dix formats) ; padron.com « Padrón Series » (lue en octobre 2026 : quinze formats, minimum deux ans et demi de vieillissement) ; padron.com « Padron Family Reserve » (lue en octobre 2026 : sept sélections, tabac vieilli dix ans) ; padron.com « Special Releases » (http://www.padron.com/xml/special_releases.xml, non datée : 80 Years, 50th Anniversary) ; padron.com « Padrón 5oth Anniversary » (humidor de 2014) ; cigar-coop.com « Cigar News: Padrón Dámaso Launched at 2015 IPCPR Trade Show » (18 juillet 2015 : Dámaso, grand-père de José O. Padrón, premier Connecticut Shade de la maison) ; cigaraficionado.com « Padrón Dámaso: Q&A with Jorge Padrón » (27 août 2015 : Connecticut d''Équateur, mild à medium) ; upi.com « Anti-Castro group claims bombings » (12 janvier 1983 : Omega 7 revendique les bombes à l''usine Padrón de Little Havana) ; holts.com « History of Padron Cigars » (17 juillet 2018 : trois bombardements de Miami entre le 26 juillet 1979 et 1983, anticastristes, Estelí depuis 1970, embargo de 1985 à 1990, mort en décembre 2017) ; cigaraficionado.com « The Padron Family: A Nicaraguan Legacy » (juillet-août 1997 : quatre bombes dont trois explosent, usine d''Estelí brûlée en 1978, Danlí depuis 1979) ; cigaraficionado.com « Padrón Looks Back at 50 » (septembre-octobre 2014 : ouverture le 8 septembre 1964, première bombe le 24 mars 1979, Serie 1926 en 2001) ; cigaraficionado.com « Padrón Stops Rolling Cigars in Honduras » (22 janvier 2007 : Danlí ne roule plus de cigares) ; cigaraficionado.com « The Making of Padrón''s Perfecto and a Mountaintop Tobacco Tour » (22 janvier 2026 : fabrique d''Estelí, ferme La Florinda) ; cigaraficionado.com « The Padron Lands » (22 janvier 2014 : fermes Donoso et Villa Vieja, Estelí) ; cigaraficionado.com « Padrón Growing First Crop on New Tobacco Farm » (26 janvier 2024 : La Florinda, Estelí) ; cigar-coop.com « Cigar News: José O. Padrón Passes Away » (5 décembre 2017 : mort à 91 ans, né le 10 juin 1926) ; cigaraficionado.com « 2021 Big Smoke Meets WhiskyFest: The Cigars of Padrón » (2 novembre 2021 : Jorge Padrón dirige la maison, 1964 Anniversary lancée en 1994)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Padrón'
UNION ALL SELECT 'Cohiba', 'fr', 'limited_eds : Cohiba Sublimes Edición Limitada 2004', (JSON_CONTAINS(`limited_eds`, '"Cohiba Sublimes Edición Limitada 2004"')) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'limited_eds : Cohiba 1966 Edición Limitada 2011', (JSON_CONTAINS(`limited_eds`, '"Cohiba 1966 Edición Limitada 2011"')) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'limited_eds : Cohiba 55 Aniversario Edición Limitada 2021', (JSON_CONTAINS(`limited_eds`, '"Cohiba 55 Aniversario Edición Limitada 2021"')) FROM `brands` WHERE `name` = 'Cohiba'
