UNION ALL SELECT 'Cohiba', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('El Laguito, La Havane — fabrique mère nommée par la page officielle d''Habanos ; des modules roulés aussi chez H. Upmann et Partagás, dit la presse du métier' AS BINARY)) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos date la création de Cohiba de 1966 et écrit que la marque fut, pendant de nombreuses années, réservée au cadeau offert à des personnalités de gouvernement et au président Fidel Castro. L''origine du cigare se raconte de deux façons. Castro dit en 1994 qu''un de ses gardes du corps fumait un cigare très aromatique, que lui roulait un ami pour son usage personnel ; il en fit étudier le mélange et les capes, et une fabrique fut fondée autour de lui. Le torcedor Eduardo Rivera raconte en 1995 que, au début des années 1960, un ami donna l''un de ses cigares à Fidel, qui ne fuma plus rien d''autre ; il roulait alors à La Corona, à La Havane, avant de passer à El Laguito. La presse spécialisée cite parmi les destinataires de ces cadeaux Tito, Nasser, Luis Echeverría et Omar Torrijos, et, en 1974, un coffret remis à des émissaires américains pour Henry Kissinger ; Castro dit en 1994 offrir surtout des Cohiba.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cohiba naquit dans le secret absolu, en 1966. Eduardo Rivera, torcedor dont les cigares personnels avaient attiré l''œil d''un garde du corps présidentiel, fut convoqué à La Havane et discrètement installé à El Laguito — un ancien hôtel particulier du quartier de Miramar. Pendant seize ans, Cohiba ne fut jamais vendue. Elle existait comme instrument diplomatique : des boîtes sans prix, offertes par Fidel Castro à des chefs d''État qui comprenaient aussitôt ce qu''ils tenaient. Willy Brandt à Bonn. François Mitterrand à Paris. Mouammar Kadhafi à Tripoli. Nelson Mandela à Johannesburg. Tous reçurent des boîtes de ce cigare sans nom.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos dates the creation of Cohiba to 1966 and writes that the brand was, for many years, reserved for gifts offered to government figures and to President Fidel Castro. The origin of the cigar is told in two ways. Castro says in 1994 that one of his bodyguards smoked a very aromatic cigar, rolled for him by a friend for his personal use; he had its blend and wrappers studied, and a factory was founded around him. The torcedor Eduardo Rivera says in 1995 that, in the early 1960s, a friend gave one of his cigars to Fidel, who smoked nothing else afterwards; he was then rolling at La Corona, in Havana, before moving to El Laguito. The specialist press cites Tito, Nasser, Luis Echeverría and Omar Torrijos among the recipients of these gifts, and, in 1974, a box handed to American emissaries for Henry Kissinger; Castro says in 1994 that he gives mostly Cohiba.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cohiba was born in absolute secrecy in 1966. Eduardo Rivera, a torcedor whose exceptional private cigars had caught the eye of a presidential bodyguard, was summoned to Havana and quietly installed at El Laguito — a former aristocratic mansion in the Miramar district. For sixteen years, Cohiba was never sold. It existed as a diplomatic instrument: boxes without price tags, offered by Fidel Castro to heads of state who understood immediately they held something extraordinary. Willy Brandt received them in Bonn. François Mitterrand in Paris. Muammar Gaddafi in Tripoli. Nelson Mandela in Johannesburg. All received boxes of this nameless cigar.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos fecha la creación de Cohiba en 1966 y escribe que la marca estuvo reservada, durante muchos años, al regalo ofrecido a personalidades de gobierno y al presidente Fidel Castro. El origen del puro se cuenta de dos maneras. Castro dice en 1994 que uno de sus guardaespaldas fumaba un puro muy aromático, que le liaba un amigo para su uso personal; hizo estudiar la mezcla y las capas, y se fundó una fábrica a su alrededor. El torcedor Eduardo Rivera cuenta en 1995 que, a principios de los años 1960, un amigo regaló uno de sus puros a Fidel, que ya no fumó otra cosa; él liaba entonces en La Corona, en La Habana, antes de pasar a El Laguito. La prensa especializada cita entre los destinatarios de esos regalos a Tito, Nasser, Luis Echeverría y Omar Torrijos y, en 1974, un cofre entregado a emisarios estadounidenses para Henry Kissinger; Castro dice en 1994 que regala sobre todo Cohiba.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cohiba nació en el secreto absoluto, en 1966. Eduardo Rivera, torcedor cuyos puros personales habían llamado la atención de un guardaespaldas presidencial, fue convocado a La Habana e instalado discretamente en El Laguito —un antiguo palacete del barrio de Miramar. Durante dieciséis años, Cohiba no se vendió jamás. Existía como instrumento diplomático: cajas sin precio, ofrecidas por Fidel Castro a jefes de Estado que comprendían enseguida lo que tenían en las manos. Willy Brandt en Bonn. François Mitterrand en París. Muamar Gadafi en Trípoli. Nelson Mandela en Johannesburgo. Todos recibieron cajas de ese puro sin nombre.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos datiert die Entstehung von Cohiba auf 1966 und schreibt, die Marke sei viele Jahre lang Geschenken an Regierungspersönlichkeiten und an Präsident Fidel Castro vorbehalten gewesen. Der Ursprung der Zigarre wird auf zwei Arten erzählt. Castro sagt 1994, einer seiner Leibwächter habe eine sehr aromatische Zigarre geraucht, die ihm ein Freund für den persönlichen Gebrauch gerollt habe; er ließ Mischung und Deckblätter untersuchen, und um ihn herum wurde eine Fabrik gegründet. Der Torcedor Eduardo Rivera erzählt 1995, ein Freund habe Anfang der 1960er Jahre eine seiner Zigarren Fidel gegeben, der danach nichts anderes mehr geraucht habe; er rollte damals bei La Corona in Havanna, bevor er zu El Laguito wechselte. Die Fachpresse nennt unter den Empfängern dieser Geschenke Tito, Nasser, Luis Echeverría und Omar Torrijos sowie 1974 eine Kassette, die amerikanischen Abgesandten für Henry Kissinger übergeben wurde; Castro sagt 1994, er verschenke vor allem Cohiba.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Cohiba entstand 1966 im vollkommenen Geheimen. Eduardo Rivera, ein Torcedor, dessen eigene Zigarren einem Leibwächter des Präsidenten aufgefallen waren, wurde nach Havanna gerufen und still in El Laguito untergebracht — einem früheren Stadtpalais im Viertel Miramar. Sechzehn Jahre lang wurde Cohiba nie verkauft. Sie bestand als diplomatisches Werkzeug: Kisten ohne Preis, von Fidel Castro Staatsoberhäuptern überreicht, die sofort begriffen, was sie in Händen hielten. Willy Brandt in Bonn. François Mitterrand in Paris. Muammar al-Gaddafi in Tripolis. Nelson Mandela in Johannesburg. Alle erhielten Kisten dieser namenlosen Zigarre.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos 把高希霸的创立定在1966年，并写道，这个品牌在许多年里专门留作礼品，赠予政府人物和菲德尔·卡斯特罗总统。这支雪茄的来历有两种说法。卡斯特罗在1994年说，他的一名警卫抽一种香气很浓的雪茄，由一位朋友为他卷制，供其个人使用；他让人研究其配方和茄衣，并围绕他建了一家工厂。卷制师爱德华多·里维拉在1995年讲述，1960年代初，一位朋友把他的一支雪茄送给了菲德尔，此后菲德尔不再抽别的；他当时在哈瓦那的 La Corona 卷制，之后才转到 El Laguito。专业媒体提到这些礼物的受赠者中有铁托、纳赛尔、路易斯·埃切维里亚和奥马尔·托里霍斯，并提到1974年交给美国使者的一个套盒，收件人是亨利·基辛格；卡斯特罗在1994年说，他送出的主要是高希霸。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('高希霸诞生于1966年，在绝对的保密之中。爱德华多·里维拉是一名卷制师，他自用的雪茄引起了一位总统警卫的注意；他被召到哈瓦那，安置在米拉马尔区一座旧宅——拉古尼托。此后十六年，高希霸从不出售。它作为外交工具而存在：没有价格的盒子，由菲德尔·卡斯特罗赠予各国元首，而他们一拿到手就明白那是什么。波恩的维利·勃兰特。巴黎的弗朗索瓦·密特朗。的黎波里的穆阿迈尔·卡扎菲。约翰内斯堡的纳尔逊·曼德拉。他们都收到过这支没有名字的雪茄。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تؤرّخ Habanos نشأة «كوهيبا» بعام 1966 وتكتب أنّ العلامة ظلّت طوال سنوات عديدة مخصّصة للهدايا التي تُقدَّم إلى شخصيات حكومية وإلى الرئيس فيدل كاسترو. وتُروى أصول السيجار على وجهين. يقول كاسترو عام 1994 إنّ أحد حرّاسه الشخصيين كان يدخّن سيجارًا شديد العطر، يلفّه له صديق لاستعماله الشخصي؛ فأمر بدراسة الخلطة والغلافات، وأُسّس مصنع حوله. ويروي اللافّ إدواردو ريفيرا عام 1995 أنّه في مطلع ستينيات القرن العشرين أهدى صديق أحد سيجاراته إلى فيدل، الذي لم يدخّن بعده شيئًا آخر؛ وكان حينها يلفّ في La Corona في هافانا قبل أن ينتقل إلى El Laguito. وتذكر الصحافة المتخصّصة بين متلقّي هذه الهدايا تيتو وناصر ولويس إتشيفيريا وعمر توريخوس، كما تذكر عام 1974 علبة سُلّمت إلى موفدين أمريكيين لهنري كيسنجر؛ ويقول كاسترو عام 1994 إنّه يهدي «كوهيبا» في الغالب.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('وُلدت «كوهيبا» في سرّية تامّة عام 1966. فقد استُدعي إدواردو ريفيرا، وهو لافّ لفتت سيجاراته الشخصية انتباه أحد حرّاس الرئيس، إلى هافانا وأُسكن بهدوء في «إل لاغيتو» — قصر قديم في حيّ ميرامار. وطوال ستّ عشرة سنة، لم تُبَع «كوهيبا» قط. كانت توجد أداةً دبلوماسية: علب بلا سعر، يقدّمها فيدل كاسترو لرؤساء دول يدركون فورًا ما يمسكون. فيلي براندت في بون. فرانسوا ميتران في باريس. معمّر القذافي في طرابلس. نيلسون مانديلا في جوهانسبرغ. جميعهم تلقّوا علبًا من هذا السيجار الذي بلا اسم.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos écrit que, depuis 1982, année où la marque est présentée dans plusieurs pays, Cohiba est disponible pour les fumeurs, en quantités limitées. La presse spécialisée situe cette première mise en vente en Espagne, au moment de la Coupe du monde, avec trois formats, Lancero, Corona Especial et Panetela ; Robusto, Exquisito et Espléndido les rejoignent en 1989. Certains récits datent le nom de 1968 plutôt que de 1966. Le nom vient d''un mot taïno désignant les feuilles de tabac roulées que Colomb vit à Cuba en 1492 ; Habanos y voit le premier nom du tabac.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('En 1982, devant la curiosité internationale et un marché noir grandissant, Cuba ouvrit Cohiba à la distribution commerciale — hors de l''île seulement, et par les canaux les plus fermés de Cubatabaco. Le nom vient du taïno, la langue des premiers habitants de Cuba : il signifie simplement tabac. L''ironie est parfaite — un cigare enveloppé de protocole porte le nom le plus ancien et le plus nu de ce qu''il est.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos writes that, since 1982, the year the brand was presented in several countries, Cohiba has been available to smokers, in limited quantities. The specialist press places this first sale in Spain, at the time of the World Cup, with three formats, Lancero, Corona Especial and Panetela; Robusto, Exquisito and Espléndido joined them in 1989. Some accounts date the name to 1968 rather than 1966. The name comes from a Taíno word for the rolled tobacco leaves that Columbus saw in Cuba in 1492; Habanos sees in it the first name of tobacco.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('In 1982, facing mounting international curiosity and a growing black market, Cuba opened Cohiba to commercial distribution — but only outside the island, and only through Cubatabaco''s most exclusive channels. The name comes from the Taíno language, spoken by Cuba''s original inhabitants before Columbus: it simply means tobacco. The irony is perfect: a cigar wrapped in protocol carries the oldest and plainest name for what it is.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos escribe que, desde 1982, año en que la marca se presenta en varios países, Cohiba está disponible para los fumadores, en cantidades limitadas. La prensa especializada sitúa esa primera puesta a la venta en España, en el momento de la Copa del Mundo, con tres formatos, Lancero, Corona Especial y Panetela; Robusto, Exquisito y Espléndido se les unen en 1989. Algunos relatos fechan el nombre en 1968 en lugar de 1966. El nombre viene de una palabra taína que designaba las hojas de tabaco enrolladas que Colón vio en Cuba en 1492; Habanos ve en él el primer nombre del tabaco.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('En 1982, ante la curiosidad internacional y un mercado negro creciente, Cuba abrió Cohiba a la distribución comercial —fuera de la isla solamente, y por los canales más cerrados de Cubatabaco. El nombre viene del taíno, la lengua de los primeros habitantes de Cuba: significa simplemente tabaco. La ironía es perfecta —un puro envuelto en protocolo lleva el nombre más antiguo y más desnudo de lo que es.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos schreibt, seit 1982, dem Jahr, in dem die Marke in mehreren Ländern vorgestellt wird, sei Cohiba für Raucher erhältlich, in begrenzten Mengen. Die Fachpresse verortet diesen ersten Verkauf in Spanien, zur Zeit der Weltmeisterschaft, mit drei Formaten, Lancero, Corona Especial und Panetela; Robusto, Exquisito und Espléndido kamen 1989 hinzu. Manche Berichte datieren den Namen auf 1968 statt auf 1966. Der Name stammt von einem Taíno-Wort für die gerollten Tabakblätter, die Kolumbus 1492 auf Kuba sah; Habanos sieht darin den ersten Namen des Tabaks.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1982 öffnete Kuba Cohiba angesichts des internationalen Interesses und eines wachsenden Schwarzmarkts dem gewerblichen Vertrieb — nur außerhalb der Insel und über die geschlossensten Kanäle von Cubatabaco. Der Name kommt aus dem Taíno, der Sprache der ersten Bewohner Kubas: Er bedeutet schlicht Tabak. Die Ironie ist vollkommen — eine in Protokoll gehüllte Zigarre trägt den ältesten und nacktesten Namen dessen, was sie ist.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos 写道，自1982年起，也就是这个品牌在多个国家亮相的那一年，高希霸面向烟民供应，数量有限。专业媒体把这次首次发售放在西班牙，时值世界杯，推出了三种规格：Lancero、Corona Especial 和 Panetela；Robusto、Exquisito 和 Espléndido 于1989年加入。有些说法把这个名字的起用时间定在1968年而非1966年。这个名字来自一个泰诺语词，指哥伦布1492年在古巴见到的卷起的烟叶；Habanos 视之为烟草的首个名称。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1982年，面对国际上的好奇与日渐扩大的黑市，古巴让高希霸进入商业分销——只在岛外，并且经由古巴烟草公司最封闭的渠道。这个名字来自泰诺语，古巴最早居民的语言，意思很简单：烟草。讽刺之处正在于此——一支层层礼仪包裹的雪茄，用的却是它自身最古老、最赤裸的名字。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تكتب Habanos أنّ «كوهيبا» متاحة للمدخّنين منذ 1982، وهي السنة التي قُدِّمت فيها العلامة في عدّة بلدان، بكميات محدودة. وتضع الصحافة المتخصّصة هذا الطرح الأول للبيع في إسبانيا، في وقت كأس العالم، بثلاثة مقاسات هي Lancero وCorona Especial وPanetela؛ وانضمّ إليها Robusto وExquisito وEspléndido عام 1989. وتؤرّخ بعض الروايات الاسم بعام 1968 بدل 1966. ويأتي الاسم من كلمة تاينو تدلّ على أوراق التبغ الملفوفة التي رآها كولومبوس في كوبا عام 1492؛ وترى Habanos فيه الاسم الأول للتبغ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وفي 1982، أمام الفضول الدولي وسوق سوداء متنامية، فتحت كوبا «كوهيبا» للتوزيع التجاري — خارج الجزيرة فقط، وعبر أضيق قنوات «كوباتاباكو». والاسم من لغة التاينو، لغة أوائل سكّان كوبا: ومعناه ببساطة التبغ. والمفارقة تامّة — سيجار ملفوف بالبروتوكول يحمل أقدم أسماء ما هو عليه وأعراها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos écrit que Cohiba est la seule de ses marques dont deux des trois types de feuilles employés, le seco et le ligero, subissent une fermentation supplémentaire, ce qui donne à la marque un arôme et une saveur reconnaissables. Les feuilles sont, dit-il, la sélection de la sélection des meilleures vegas de San Juan y Martínez et de San Luis, dans la Vuelta Abajo. La presse spécialisée parle, elle, d''une troisième fermentation en barriques, décidée à El Laguito en 1965-1966 pour adoucir le goût.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Ce qui distingue techniquement Cohiba, c''est la troisième fermentation. Après les deux que subit tout tabac cubain, ses feuilles passent par une fermentation prolongée supplémentaire, en fûts de cèdre. Le procédé, tenu secret, retire une dernière couche d''âpreté et développe cet équilibre complexe, presque crémeux, qui définit le profil de la marque. Les feuilles viennent exclusivement de la Vuelta Abajo, la région la plus prestigieuse de Cuba, et sont choisies par les maîtres assembleurs de la manufacture.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos writes that Cohiba is the only one of its brands in which two of the three types of leaf used, the seco and the ligero, undergo an additional fermentation, which gives the brand a recognisable aroma and flavour. The leaves are, it says, the selection of the selection of the best vegas of San Juan y Martínez and San Luis, in the Vuelta Abajo. The specialist press, for its part, speaks of a third fermentation in barrels, decided at El Laguito in 1965-1966 to soften the taste.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('What makes Cohiba technically distinct is the third fermentation. After the standard two fermentations undergone by all Cuban tobacco, Cohiba''s leaves undergo a third extended fermentation in cedar barrels. This process, closely guarded and unique in the industry, extracts a final layer of harshness and develops the complex, almost creamy equilibrium that defines the brand''s profile. The leaves come exclusively from Vuelta Abajo, Cuba''s most prestigious growing region, and are selected personally by the factory''s master blenders.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos escribe que Cohiba es la única de sus marcas en la que dos de los tres tipos de hojas empleados, el seco y el ligero, sufren una fermentación suplementaria, lo que da a la marca un aroma y un sabor reconocibles. Las hojas son, dice, la selección de la selección de las mejores vegas de San Juan y Martínez y de San Luis, en la Vuelta Abajo. La prensa especializada habla, por su parte, de una tercera fermentación en barricas, decidida en El Laguito en 1965-1966 para suavizar el sabor.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Lo que distingue técnicamente a Cohiba es la tercera fermentación. Después de las dos que sufre todo tabaco cubano, sus hojas pasan por una fermentación prolongada suplementaria, en barricas de cedro. El procedimiento, mantenido en secreto, retira una última capa de aspereza y desarrolla ese equilibrio complejo, casi cremoso, que define el perfil de la marca. Las hojas vienen exclusivamente de la Vuelta Abajo, la región más prestigiosa de Cuba, y las escogen los maestros ligadores de la manufactura.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos schreibt, Cohiba sei die einzige seiner Marken, bei der zwei der drei verwendeten Blatttypen, das Seco und das Ligero, eine zusätzliche Fermentation durchlaufen, was der Marke ein wiedererkennbares Aroma und einen wiedererkennbaren Geschmack verleihe. Die Blätter seien, so Habanos, die Auswahl der Auswahl der besten Vegas von San Juan y Martínez und San Luis in der Vuelta Abajo. Die Fachpresse spricht dagegen von einer dritten Fermentation in Fässern, die 1965-1966 in El Laguito beschlossen worden sei, um den Geschmack zu mildern.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Was Cohiba technisch auszeichnet, ist die dritte Fermentation. Nach den beiden, die jeder kubanische Tabak durchläuft, gehen ihre Blätter durch eine zusätzliche verlängerte Fermentation in Zedernfässern. Das geheim gehaltene Verfahren nimmt eine letzte Schicht Herbheit und entwickelt jenes vielschichtige, beinahe cremige Gleichgewicht, das das Profil der Marke bestimmt. Die Blätter stammen ausschließlich aus der Vuelta Abajo, der angesehensten Gegend Kubas, und werden von den Meistermischern der Manufaktur ausgewählt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Habanos 写道，高希霸是其旗下唯一的这样一个品牌：所用三类叶子中，seco 和 ligero 两类要经过额外发酵，因此品牌有了可辨认的香气和风味。据其所说，这些叶子是 Vuelta Abajo 的 San Juan y Martínez 和 San Luis 两地顶级 vegas 的精选中的精选。专业媒体则提到第三次发酵，在木桶中进行，1965至1966年在 El Laguito 决定采用，目的是让口味更柔和。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('在技术上使高希霸与众不同的，是第三次发酵。在所有古巴烟草都要经历的两次之后，它的叶子还要在雪松木桶里再经一次延长发酵。这道保密的工序去掉最后一层粗涩，养出定义了这个品牌风格的那种复杂而近乎奶油般的均衡。叶子全部来自阿巴霍谷——古巴最负盛名的产区——并由工厂的调配大师挑选。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تكتب Habanos أنّ «كوهيبا» هي العلامة الوحيدة بين علاماتها التي يخضع فيها نوعان من أنواع الأوراق الثلاثة المستعملة، هما seco وligero، لتخمير إضافي، ما يمنح العلامة رائحة ونكهة يمكن التعرّف عليهما. والأوراق هي، كما تقول، منتقى المنتقى من خيرة الـvegas في San Juan y Martínez وSan Luis، في Vuelta Abajo. أمّا الصحافة المتخصّصة فتتحدّث عن تخمير ثالث في براميل، قُرّر في El Laguito في 1965-1966 لتلطيف المذاق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وما يميّز «كوهيبا» تقنيًّا هو التخمير الثالث. فبعد التخميرين اللذين يمرّ بهما كل تبغ كوبي، تمرّ أوراقها بتخمير مطوَّل إضافي في براميل من خشب الأرز. وهذه العملية، المحفوظة سرًّا، تنزع طبقة أخيرة من الخشونة وتنمّي ذلك التوازن المركّب، القشدي تقريبًا، الذي يحدّد طابع العلامة. والأوراق تأتي حصرًا من فويلتا أباخو، أعرق مناطق كوبا، ويختارها معلّمو الخلط في المصنع.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Laguito a employé un temps uniquement des torcedoras, écrit la presse spécialisée en 2016. La fabrique est normalement fermée au grand public : Habanos y organise des visites guidées pour les participants de ses événements, comme en septembre 2022 pour les 55 ans de la marque.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El Laguito est le monde de Cohiba. Son personnel est majoritairement féminin — les torcedoras qui roulent Cohiba sont les artisanes du cigare les mieux payées de Cuba. La manufacture ne reçoit pas de visiteurs. Chaque cigare qui en sort passe par une série de points de contrôle, et les rebuts — environ un sur cinq — sont détruits, jamais redistribués.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Laguito employed only torcedoras for a time, the specialist press writes in 2016. The factory is normally closed to the general public: Habanos organises guided visits there for participants in its events, as in September 2022 for the brand''s 55th anniversary.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El Laguito is Cohiba''s world. Its workforce is predominantly female — the torcedoras who roll Cohiba are Cuba''s highest-paid cigar artisans. The factory does not receive visitors. Its rhythms are its own. Each cigar leaving El Laguito passes through a series of quality control checkpoints. Rejected cigars — roughly one in five — are destroyed, never redistributed.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Laguito empleó durante un tiempo únicamente torcedoras, escribe la prensa especializada en 2016. La fábrica está normalmente cerrada al gran público: Habanos organiza allí visitas guiadas para los participantes en sus eventos, como en septiembre de 2022 por los 55 años de la marca.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El Laguito es el mundo de Cohiba. Su personal es mayoritariamente femenino —las torcedoras que lían Cohiba son las artesanas del puro mejor pagadas de Cuba. La manufactura no recibe visitantes. Cada puro que sale de ella pasa por una serie de puntos de control, y los descartes —alrededor de uno de cada cinco— se destruyen, nunca se redistribuyen.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Laguito beschäftigte eine Zeit lang nur Torcedoras, schreibt die Fachpresse 2016. Die Fabrik ist normalerweise für die breite Öffentlichkeit geschlossen: Habanos organisiert dort Führungen für die Teilnehmer seiner Veranstaltungen, so im September 2022 zum 55-jährigen Bestehen der Marke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El Laguito ist die Welt von Cohiba. Die Belegschaft ist überwiegend weiblich — die Torcedoras, die Cohiba rollen, sind die bestbezahlten Zigarrenhandwerkerinnen Kubas. Die Manufaktur empfängt keine Besucher. Jede Zigarre, die sie verlässt, durchläuft eine Reihe von Prüfpunkten, und der Ausschuss — etwa jede fünfte — wird vernichtet, nie weitergegeben.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El Laguito 曾有一段时间只雇用女卷制师，专业媒体在2016年这样写道。这家工厂通常不对公众开放：Habanos 在那里为其活动的参与者组织导览参观，例如2022年9月为品牌55周年举办的那次。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('拉古尼托是高希霸的世界。厂里以女性为主——卷制高希霸的女卷制师是古巴报酬最高的雪茄手艺人。工厂不接待访客。每一支出厂的雪茄都要经过一系列检查点，废品——大约五分之一——就地销毁，绝不流出。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('وظّف El Laguito لفترة لافّات فقط، كما تكتب الصحافة المتخصّصة عام 2016. والمصنع مغلق عادةً أمام عامّة الجمهور: تنظّم Habanos فيه زيارات مصحوبة بمرشدين للمشاركين في فعالياتها، كما في أيلول/سبتمبر 2022 لمناسبة مرور 55 عامًا على العلامة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('«إل لاغيتو» هو عالم «كوهيبا». عاملاته أغلبية — فاللافّات اللواتي يلففن «كوهيبا» هنّ أعلى حرفيّات السيجار أجرًا في كوبا. ولا يستقبل المصنع زوّارًا. وكل سيجار يخرج منه يمرّ بسلسلة نقاط تفتيش، والمرفوض منه — نحو واحد من كل خمسة — يُتلَف ولا يُعاد توزيعه أبدًا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('La bague noir et jaune est la signature visuelle de la marque. Habanos a introduit en 2014 une nouvelle bague à hologramme, d''abord sur la Pirámides Extra puis sur toute la Línea Clásica et la Línea 1492, pour mieux tracer chaque cigare ; la ligne Behike portait depuis 2010 sa propre bague à mesures de sécurité renforcées.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('La bague noir et jaune est devenue un signe de statut bien au-delà du monde du tabac. Elle apparaît au cinéma, en littérature, dans la photographie politique, comme raccourci de pouvoir. Les contrefaçons de bagues circulent largement, ce qui en dit plus long sur la diffusion de la marque qu''aucun chiffre de vente.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('The black and yellow band is the visual signature of the brand. In 2014 Habanos introduced a new hologram band, first on the Pirámides Extra and then across the whole Línea Clásica and Línea 1492, so as to trace each cigar better; the Behike line had carried, since 2010, its own band with reinforced security measures.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('The Cohiba band, with its distinctive black and yellow design, has become a universal symbol of status extending far beyond the tobacco world. It appears in film, literature, and political photography as shorthand for power. Counterfeit bands circulate widely, which says more about the brand''s reach than any sales figure would.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('La anilla negra y amarilla es la firma visual de la marca. Habanos introdujo en 2014 una nueva anilla con holograma, primero en el Pirámides Extra y luego en toda la Línea Clásica y la Línea 1492, para rastrear mejor cada puro; la línea Behike llevaba desde 2010 su propia anilla con medidas de seguridad reforzadas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('La anilla negra y amarilla se ha vuelto un signo de estatus mucho más allá del mundo del tabaco. Aparece en el cine, en la literatura, en la fotografía política, como atajo de poder. Las falsificaciones de anillas circulan ampliamente, lo que dice más de la difusión de la marca que ninguna cifra de ventas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
