UNION ALL SELECT 'Cohiba', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Die schwarz-gelbe Banderole ist weit über die Welt des Tabaks hinaus zum Standeszeichen geworden. Sie erscheint im Film, in der Literatur, in der politischen Fotografie als Kürzel für Macht. Gefälschte Banderolen sind weit verbreitet, was über die Verbreitung der Marke mehr sagt als jede Verkaufszahl.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('黑黄相间的烟标是这个品牌的视觉标志。Habanos 于2014年推出了带全息图的新烟标，先用在 Pirámides Extra 上，随后用于整条 Línea Clásica 和 Línea 1492，以便更好地追踪每一支雪茄；Behike 产品线自2010年起就带有自己的烟标，其安全措施有所加强。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
