UNION ALL SELECT 'Cohiba', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وصارت الحلقة السوداء والصفراء علامة مكانة تتجاوز عالم التبغ بكثير. تظهر في السينما وفي الأدب وفي التصوير السياسي اختصارًا للسلطة. وتنتشر الحلقات المزوّرة على نطاق واسع، وهو ما يقول عن انتشار العلامة أكثر مما يقوله أي رقم مبيعات.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 6 (nouveau texte)', (LOCATE(CAST('La ligne Behike, lancée en 2010, est décrite par Habanos comme la plus exclusive qu''il ait lancée. Elle est la première de la marque à intégrer le medio tiempo à son assemblage, une feuille issue des deux feuilles supérieures du plant de tabac de plein soleil. Elle est née avec trois formats, BHK 52, 54 et 56, roulés à El Laguito ; un quatrième, le BHK 58 (58 x 178 mm), présenté au Festival del Habano en février 2025, a été vendu pour la première fois en Suisse à partir de février 2026, dans un coffret de quatre formats célébrant les quinze ans de la ligne.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'fr', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('La ligne Behike BHK, lancée en 2010 pour les quarante-quatre ans de la marque, a poussé le principe plus loin : elle emploie le medio tiempo, une feuille qui ne pousse qu''à la cime du plant, en quantités trop faibles pour une récolte à grande échelle. Moins de trois mille boîtes existent chaque année.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 6 (nouveau texte)', (LOCATE(CAST('The Behike line, launched in 2010, is described by Habanos as the most exclusive it has launched. It is the first in the brand to bring the medio tiempo into its blend, a leaf taken from the two uppermost leaves of the sun-grown tobacco plant. It was born with three formats, BHK 52, 54 and 56, rolled at El Laguito; a fourth, the BHK 58 (58 x 178 mm), presented at the Festival del Habano in February 2025, was sold for the first time in Switzerland from February 2026, in a boxed set of four formats celebrating fifteen years of the line.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'en', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('The Behike BHK line, launched in 2010 for the brand''s 44th anniversary, pushed the concept further still: using the ultra-rare medio tiempo leaf — found only at the very crown of the tobacco plant, in quantities too small to harvest at scale — it produced the most ambitious cigar the brand has released. Fewer than three thousand boxes exist per year.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 6 (nouveau texte)', (LOCATE(CAST('La línea Behike, lanzada en 2010, es descrita por Habanos como la más exclusiva que ha lanzado. Es la primera de la marca en integrar el medio tiempo en su ligada, una hoja procedente de las dos hojas superiores de la planta de tabaco de pleno sol. Nació con tres formatos, BHK 52, 54 y 56, liados en El Laguito; un cuarto, el BHK 58 (58 x 178 mm), presentado en el Festival del Habano en febrero de 2025, se vendió por primera vez en Suiza a partir de febrero de 2026, en un estuche de cuatro formatos que celebra los quince años de la línea.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'es', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('La línea Behike BHK, lanzada en 2010 por los cuarenta y cuatro años de la marca, llevó el principio más lejos: emplea el medio tiempo, una hoja que solo crece en la cima de la planta, en cantidades demasiado escasas para una cosecha a gran escala. Existen menos de tres mil cajas cada año.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Die Linie Behike, 2010 eingeführt, wird von Habanos als die exklusivste Linie beschrieben, die es herausgebracht hat. Sie ist die erste der Marke, die das Medio Tiempo in ihre Mischung aufnimmt, ein Blatt von den beiden obersten Blättern der in voller Sonne angebauten Tabakpflanze. Sie entstand mit drei Formaten, BHK 52, 54 und 56, in El Laguito gerollt; ein viertes, der BHK 58 (58 x 178 mm), im Februar 2025 auf dem Festival del Habano vorgestellt, wurde ab Februar 2026 erstmals in der Schweiz verkauft, in einer Kassette mit vier Formaten zum fünfzehnjährigen Bestehen der Linie.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba'
UNION ALL SELECT 'Cohiba', 'de', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('Die Linie Behike BHK, 2010 zum vierundvierzigsten Jahr der Marke herausgebracht, trieb den Grundsatz weiter: Sie verwendet das Medio Tiempo, ein Blatt, das nur an der Spitze der Pflanze wächst, in Mengen, die für eine großflächige Ernte zu gering sind. Weniger als dreitausend Kisten gibt es jedes Jahr.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
