UNION ALL SELECT 'Cohiba', 'zh', 'histoire 6 (ancien texte parti)', (LOCATE(CAST('2010年为品牌四十四周年推出的 Behike BHK 产品线，把这条原则推得更远：它使用「medio tiempo」——只长在烟株顶端的叶子，产量少到无法大规模采收。每年存在的盒子不到三千。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba'
