UNION ALL SELECT 'Cohiba', 'es', 'gamme Línea Clásica (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_es`, '$[1].vitolas')) = 8) FROM `brands` WHERE `name` = 'Cohiba'
