UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar Company a déposé la marque COHIBA à l''Office américain des brevets et marques le 13 mars 1978 ; l''enregistrement date du 17 février 1981. Cubatabaco avait déposé la sienne à Cuba en septembre 1969 et obtenu l''enregistrement le 31 mai 1972, rappelle la presse spécialisée à propos de la décision de 2025. General Cigar a développé sa propre ligne Cohiba pour le marché américain, d''abord roulée uniquement en République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar Company déposa la marque Cohiba aux États-Unis en 1978, plusieurs années avant que Habanos S.A. n''entreprenne ses propres démarches d''enregistrement américain. L''embargo commercial américain contre Cuba — en vigueur depuis 1962 — rendait la marque cubaine légalement inexistante sur le sol américain. General Cigar saisit cette opportunité et créa sa propre gamme Cohiba pour le marché américain, fabriquée en République Dominicaine.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar Company filed the COHIBA trademark with the United States Patent and Trademark Office on 13 March 1978; the registration dates from 17 February 1981. Cubatabaco had filed its own in Cuba in September 1969 and obtained registration on 31 May 1972, the specialist press recalls in connection with the 2025 decision. General Cigar developed its own Cohiba line for the American market, at first rolled only in the Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar Company registered the Cohiba trademark in the United States in 1978, several years before Habanos S.A. pursued its own American registration. The US trade embargo against Cuba — in effect since 1962 — rendered the Cuban brand legally nonexistent on American soil. General Cigar seized this opportunity and created its own Cohiba range for the American market, manufactured in the Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar Company depositó la marca COHIBA en la Oficina de Patentes y Marcas de Estados Unidos el 13 de marzo de 1978; el registro data del 17 de febrero de 1981. Cubatabaco había depositado la suya en Cuba en septiembre de 1969 y obtuvo el registro el 31 de mayo de 1972, recuerda la prensa especializada a propósito de la decisión de 2025. General Cigar desarrolló su propia línea Cohiba para el mercado estadounidense, al principio torcida únicamente en la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar Company registró la marca Cohiba en Estados Unidos en 1978, varios años antes de que Habanos S.A. iniciara sus propios trámites de registro estadounidense. El embargo comercial estadounidense contra Cuba —vigente desde 1962— hacía que la marca cubana fuera legalmente inexistente en suelo estadounidense. General Cigar aprovechó la oportunidad y creó su propia gama Cohiba para el mercado estadounidense, fabricada en la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die General Cigar Company meldete die Marke COHIBA am 13. März 1978 beim Patent- und Markenamt der Vereinigten Staaten an; die Eintragung datiert vom 17. Februar 1981. Cubatabaco hatte ihre eigene im September 1969 in Kuba angemeldet und die Eintragung am 31. Mai 1972 erhalten, wie die Fachpresse anlässlich der Entscheidung von 2025 in Erinnerung ruft. General Cigar entwickelte eine eigene Cohiba-Linie für den amerikanischen Markt, die zunächst ausschließlich in der Dominikanischen Republik gerollt wurde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die General Cigar Company ließ die Marke Cohiba 1978 in den Vereinigten Staaten eintragen, mehrere Jahre bevor Habanos S.A. eine eigene amerikanische Anmeldung betrieb. Das seit 1962 geltende US-Handelsembargo gegen Kuba machte die kubanische Marke auf amerikanischem Boden rechtlich nicht existent. General Cigar ergriff diese Gelegenheit und schuf eine eigene Cohiba-Linie für den amerikanischen Markt, hergestellt in der Dominikanischen Republik.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('General Cigar Company 于 1978年3月13日向美国专利商标局提交了 COHIBA 商标申请；该商标的注册日期为 1981年2月17日。Cubatabaco 曾于 1969年9月在古巴提交了自己的商标申请，并于 1972年5月31日获得注册，专业媒体在报道 2025年的裁决时如此回顾。General Cigar 为美国市场开发了自己的 Cohiba 产品线，起初仅在多米尼加共和国卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('General Cigar 公司于 1978 年在美国注册了 Cohiba 商标，比 Habanos S.A. 着手办理自己的美国注册手续早了数年。自 1962 年起生效的美国对古巴贸易禁运，使这个古巴品牌在美国境内于法律上并不存在。General Cigar 抓住这一机会，为美国市场创立了自己的 Cohiba 系列，在多米尼加共和国生产。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('أودعت General Cigar Company علامة COHIBA لدى مكتب البراءات والعلامات التجارية الأمريكي في 13 مارس 1978، ويعود تاريخ تسجيلها إلى 17 فبراير 1981. وكانت Cubatabaco قد أودعت علامتها في كوبا في سبتمبر 1969 وحصلت على التسجيل في 31 مايو 1972، كما تذكّر الصحافة المتخصصة في سياق الحديث عن قرار عام 2025. وطوّرت General Cigar خطاً خاصاً بها من Cohiba للسوق الأمريكية، كان يُلفّ في البداية في جمهورية الدومينيكان وحدها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('سجّلت شركة General Cigar علامة Cohiba في الولايات المتحدة عام 1978، قبل سنوات من شروع Habanos S.A. في إجراءات تسجيلها الأمريكية الخاصة. وكان الحظر التجاري الأمريكي على كوبا — الساري منذ 1962 — يجعل العلامة الكوبية معدومة قانونياً على الأراضي الأمريكية. فاغتنمت General Cigar الفرصة وأنشأت تشكيلة Cohiba خاصة بها للسوق الأمريكية، تُصنع في جمهورية الدومينيكان.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Cubatabaco demande en janvier 1997 l''enregistrement de COHIBA et l''annulation des marques de General Cigar auprès de l''Office des marques, puis assigne General Cigar devant le tribunal fédéral du sud de New York le 12 novembre 1997. En mars 2004, le juge Robert Sweet interdit à General Cigar d''utiliser la marque et annule ses enregistrements ; en février 2005, la Cour d''appel du 2e circuit renverse cette décision, jugeant que l''embargo interdit à une entreprise cubaine d''acquérir des droits de propriété aux États-Unis. Le dossier, rouvert en 2008, voit le juge Sweet donner de nouveau raison à Cubatabaco en décembre 2009, puis la Cour d''appel donner raison à General Cigar en juillet 2010. Devant l''Office des marques (TTAB), la demande d''annulation de Cubatabaco est rejetée en mars 2013 ; la Cour d''appel du circuit fédéral annule ce rejet le 4 juin 2014, et la Cour suprême refuse d''examiner le recours de General Cigar le 23 février 2015. En décembre 2022, le TTAB ordonne l''annulation des deux enregistrements américains de General Cigar, sur le fondement de la Convention interaméricaine de 1929. General Cigar saisit en février 2023 le tribunal fédéral de Virginie orientale, qui confirme cette annulation en mai 2025 (juge Leonie Brinkema) ; General Cigar a fait appel devant la Cour d''appel du 4e circuit. STG, sa maison mère, dit que les enregistrements fédéraux restent valides pendant l''appel et que les droits issus de l''usage prolongé de la marque aux États-Unis ne sont pas touchés.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Habanos S.A. contesta cette appropriation à partir des années 1990. Les tribunaux américains rendirent des décisions contradictoires selon les juridictions et les années. En 2004, une décision favorable à General Cigar confirma leur droit de commercialiser Cohiba aux États-Unis. En 2007, un appel renversa partiellement cette décision. Le dossier est l''un des plus longs et complexes de l''histoire du droit des marques américain.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('In January 1997 Cubatabaco applied to the Trademark Office to register COHIBA and to cancel General Cigar''s marks, then sued General Cigar in the federal court for the Southern District of New York on 12 November 1997. In March 2004, Judge Robert Sweet barred General Cigar from using the mark and cancelled its registrations; in February 2005, the Court of Appeals for the Second Circuit reversed that decision, holding that the embargo bars a Cuban company from acquiring property rights in the United States. The case, reopened in 2008, saw Judge Sweet again rule in favour of Cubatabaco in December 2009, then the Court of Appeals rule in favour of General Cigar in July 2010. Before the Trademark Trial and Appeal Board (TTAB), Cubatabaco''s cancellation petition was rejected in March 2013; the Court of Appeals for the Federal Circuit set aside that rejection on 4 June 2014, and the Supreme Court declined to hear General Cigar''s appeal on 23 February 2015. In December 2022, the TTAB ordered the cancellation of both of General Cigar''s American registrations, on the basis of the 1929 Inter-American Convention. In February 2023 General Cigar brought the matter before the federal court for the Eastern District of Virginia, which upheld that cancellation in May 2025 (Judge Leonie Brinkema); General Cigar has appealed to the Court of Appeals for the Fourth Circuit. STG, its parent company, says that the federal registrations remain valid during the appeal and that the rights arising from the prolonged use of the mark in the United States are not affected.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Habanos S.A. challenged this appropriation starting in the 1990s. American courts rendered contradictory decisions across jurisdictions and years. In 2004, a ruling favorable to General Cigar confirmed their right to market Cohiba in the US. In 2007, an appeal partially reversed this decision. The case is one of the longest and most complex in the history of American trademark law.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Cubatabaco solicitó en enero de 1997 el registro de COHIBA y la anulación de las marcas de General Cigar ante la Oficina de Marcas, y luego demandó a General Cigar ante el tribunal federal del Distrito Sur de Nueva York el 12 de noviembre de 1997. En marzo de 2004, el juez Robert Sweet prohibió a General Cigar utilizar la marca y anuló sus registros; en febrero de 2005, el Tribunal de Apelaciones del Segundo Circuito revocó esa decisión, al considerar que el embargo impide a una empresa cubana adquirir derechos de propiedad en Estados Unidos. En el expediente, reabierto en 2008, el juez Sweet volvió a dar la razón a Cubatabaco en diciembre de 2009, y después el Tribunal de Apelaciones se la dio a General Cigar en julio de 2010. Ante la Junta de Juicios y Apelaciones de Marcas (TTAB), la solicitud de anulación de Cubatabaco fue rechazada en marzo de 2013; el Tribunal de Apelaciones del Circuito Federal anuló ese rechazo el 4 de junio de 2014, y el Tribunal Supremo se negó a examinar el recurso de General Cigar el 23 de febrero de 2015. En diciembre de 2022, la TTAB ordenó la anulación de los dos registros estadounidenses de General Cigar, con fundamento en la Convención Interamericana de 1929. General Cigar acudió en febrero de 2023 al tribunal federal del Distrito Este de Virginia, que confirmó esa anulación en mayo de 2025 (jueza Leonie Brinkema); General Cigar ha apelado ante el Tribunal de Apelaciones del Cuarto Circuito. STG, su empresa matriz, dice que los registros federales siguen vigentes durante la apelación y que los derechos derivados del uso prolongado de la marca en Estados Unidos no se ven afectados.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Habanos S.A. impugnó esa apropiación a partir de los años noventa. Los tribunales estadounidenses dictaron resoluciones contradictorias según la jurisdicción y el año. En 2004, una sentencia favorable a General Cigar confirmó su derecho a comercializar Cohiba en Estados Unidos. En 2007, una apelación revocó parcialmente esa decisión. El expediente es uno de los más largos y complejos de la historia del derecho de marcas estadounidense.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Cubatabaco beantragte im Januar 1997 beim Markenamt die Eintragung von COHIBA und die Löschung der Marken von General Cigar und verklagte General Cigar dann am 12. November 1997 vor dem Bundesgericht für den südlichen Bezirk von New York. Im März 2004 untersagte Richter Robert Sweet General Cigar die Verwendung der Marke und löschte deren Eintragungen; im Februar 2005 hob das Bundesberufungsgericht des Zweiten Bezirks diese Entscheidung auf mit der Begründung, das Embargo verbiete einem kubanischen Unternehmen den Erwerb von Eigentumsrechten in den Vereinigten Staaten. In dem 2008 wieder aufgenommenen Verfahren gab Richter Sweet im Dezember 2009 erneut Cubatabaco recht, woraufhin das Berufungsgericht im Juli 2010 General Cigar recht gab. Vor der Beschwerdekammer für Marken (TTAB) wurde der Löschungsantrag von Cubatabaco im März 2013 abgewiesen; das Bundesberufungsgericht des Federal Circuit hob diese Abweisung am 4. Juni 2014 auf, und der Oberste Gerichtshof der Vereinigten Staaten lehnte es am 23. Februar 2015 ab, sich mit dem Rechtsmittel von General Cigar zu befassen. Im Dezember 2022 ordnete die TTAB die Löschung der beiden amerikanischen Eintragungen von General Cigar an, gestützt auf das Interamerikanische Abkommen von 1929. General Cigar rief im Februar 2023 das Bundesgericht für den östlichen Bezirk von Virginia an, das diese Löschung im Mai 2025 bestätigte (Richterin Leonie Brinkema); General Cigar hat vor dem Bundesberufungsgericht des Vierten Bezirks Berufung eingelegt. STG, ihre Muttergesellschaft, sagt, die Bundeseintragungen blieben während der Berufung gültig, und die aus der langjährigen Benutzung der Marke in den Vereinigten Staaten erwachsenen Rechte seien nicht berührt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Ab den 1990er Jahren focht Habanos S.A. diese Aneignung an. Die amerikanischen Gerichte entschieden je nach Gerichtsbarkeit und Jahr widersprüchlich. 2004 bestätigte ein für General Cigar günstiges Urteil deren Recht, Cohiba in den Vereinigten Staaten zu vertreiben. 2007 hob ein Berufungsverfahren diese Entscheidung teilweise auf. Der Fall gehört zu den längsten und verwickeltsten der amerikanischen Markenrechtsgeschichte.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Cubatabaco 于 1997年1月向商标局申请注册 COHIBA，并请求撤销 General Cigar 的商标，随后于 1997年11月12日在纽约南区联邦法院起诉 General Cigar。2004年3月，Robert Sweet 法官禁止 General Cigar 使用该商标并撤销其注册；2005年2月，联邦第二巡回上诉法院推翻了这一裁决，认定禁运使古巴企业不得在美国取得财产权利。该案于 2008年重启后，Sweet 法官于 2009年12月再度判 Cubatabaco 胜诉，随后上诉法院于 2010年7月判 General Cigar 胜诉。在商标审判和上诉委员会（TTAB），Cubatabaco 的撤销申请于 2013年3月被驳回；联邦巡回上诉法院于 2014年6月4日撤销了这一驳回，美国联邦终审法院于 2015年2月23日拒绝审理 General Cigar 的上诉。2022年12月，TTAB 裁令撤销 General Cigar 的两项美国注册，依据是 1929年的《美洲国家间公约》。General Cigar 于 2023年2月诉至弗吉尼亚东区联邦法院，该院于 2025年5月维持了这一撤销裁决（Leonie Brinkema 法官）；General Cigar 已向联邦第四巡回上诉法院提出上诉。其母公司 STG 称，上诉期间联邦注册仍然有效，且因在美国长期使用该商标而产生的权利不受影响。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Habanos S.A. 从 1990 年代起对这一占用提出异议。美国法院因管辖法院和年份不同而作出相互矛盾的判决。2004 年，一项有利于 General Cigar 的判决确认了其在美国销售 Cohiba 的权利；2007 年，一次上诉又部分推翻了该判决。此案是美国商标法史上历时最久、纠葛最深的案件之一。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('طلبت Cubatabaco في يناير 1997 لدى مكتب العلامات التجارية تسجيل COHIBA وإلغاء علامات General Cigar، ثم رفعت دعوى على General Cigar أمام المحكمة الفيدرالية للمنطقة الجنوبية من نيويورك في 12 نوفمبر 1997. وفي مارس 2004 منع القاضي Robert Sweet شركة General Cigar من استخدام العلامة وألغى تسجيلاتها؛ وفي فبراير 2005 نقضت محكمة الاستئناف للدائرة الثانية هذا القرار، معتبرةً أن الحظر يمنع شركة كوبية من اكتساب حقوق الملكية في الولايات المتحدة. وفي الملف الذي أُعيد فتحه عام 2008، حكم القاضي Sweet لصالح Cubatabaco مجدداً في ديسمبر 2009، ثم حكمت محكمة الاستئناف لصالح General Cigar في يوليو 2010. وأمام هيئة المحاكمة والاستئناف للعلامات التجارية (TTAB) رُفض طلب Cubatabaco بالإلغاء في مارس 2013؛ فألغت محكمة الاستئناف للدائرة الفيدرالية هذا الرفض في 4 يونيو 2014، ورفضت المحكمة العليا النظر في طعن General Cigar في 23 فبراير 2015. وفي ديسمبر 2022 أمرت TTAB بإلغاء تسجيلَي General Cigar الأمريكيين، استناداً إلى اتفاقية الدول الأمريكية لعام 1929. ثم لجأت General Cigar في فبراير 2023 إلى المحكمة الفيدرالية لشرق ولاية فيرجينيا، التي أيّدت هذا الإلغاء في مايو 2025 (القاضية Leonie Brinkema)؛ واستأنفت General Cigar أمام محكمة الاستئناف للدائرة الرابعة. وتقول STG، الشركة الأم لها، إن التسجيلات الفيدرالية تبقى سارية أثناء الاستئناف، وإن الحقوق الناشئة عن الاستخدام الطويل للعلامة في الولايات المتحدة لا تتأثر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('اعترضت Habanos S.A. على هذا الاستيلاء ابتداءً من التسعينيات. وأصدرت المحاكم الأمريكية أحكاماً متناقضة باختلاف الولايات القضائية والسنوات. ففي 2004 أكّد حكم لصالح General Cigar حقّها في تسويق Cohiba في الولايات المتحدة، وفي 2007 نقض الاستئناف ذلك الحكم جزئياً. والملف من أطول ملفات تاريخ قانون العلامات التجارية الأمريكي وأشدّها تعقيداً.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Une Cohiba américaine se fabrique hors de Cuba : en République dominicaine pour les Red Dot, Blue et Macassar (la Blue à General Cigar Dominicana, à Santiago), au Nicaragua à STG Estelí pour la Nicaragua et la Riviera, au Honduras pour la Royale et la Rubicon, et à Miami, chez El Titan de Bronze, pour la Serie M. Le site cohiba.com, qui porte en 2026 le copyright de Forged Cigar Co., Inc., liste neuf lignes permanentes — Red Dot, Riviera, Blue, Macassar, Black, Nicaragua, Royale, Connecticut, Rubicon —, quatre éditions limitées — Spectre, Weller, Serie M, C8 — et trois lignes retirées. Cigar Coop écrit en août 2026 que STG a transféré la marque de General Cigar Company à Forged Cigar Company, une autre filiale du groupe.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Le résultat pratique : les États-Unis sont le seul marché au monde où deux marques entièrement différentes portent le nom Cohiba. La version américaine de General Cigar utilise du tabac dominicain et hondurien. Son profil — plus doux, plus accessible, axé sur la régularité — diffère radicalement de la version cubaine. Les deux coexistent légalement et commercialement depuis des décennies, à la confusion durable des amateurs non avertis.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('An American Cohiba is made outside Cuba: in the Dominican Republic for the Red Dot, Blue and Macassar (the Blue at General Cigar Dominicana, in Santiago), in Nicaragua at STG Estelí for the Nicaragua and the Riviera, in Honduras for the Royale and the Rubicon, and in Miami, at El Titan de Bronze, for the Serie M. The website cohiba.com, which in 2026 carries the copyright of Forged Cigar Co., Inc., lists nine permanent lines (Red Dot, Riviera, Blue, Macassar, Black, Nicaragua, Royale, Connecticut, Rubicon), four limited editions (Spectre, Weller, Serie M, C8) and three discontinued lines. Cigar Coop writes in August 2026 that STG transferred the brand from General Cigar Company to Forged Cigar Company, another subsidiary of the group.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The practical result: the United States is the only market in the world where two entirely different brands carry the name Cohiba. General Cigar''s American version uses Dominican and Honduran tobacco. Its profile — softer, more accessible, focused on consistency — differs radically from the Cuban version. Both coexist legally and commercially, to the lasting confusion of uninformed enthusiasts.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Una Cohiba estadounidense se fabrica fuera de Cuba: las Red Dot, Blue y Macassar, en la República Dominicana (la Blue en General Cigar Dominicana, en Santiago); la Nicaragua y la Riviera, en Nicaragua, en STG Estelí; la Royale y la Rubicon, en Honduras; y la Serie M, en Miami, en El Titan de Bronze. El sitio cohiba.com, que en 2026 lleva el aviso de derechos de autor de Forged Cigar Co., Inc., enumera nueve líneas permanentes (Red Dot, Riviera, Blue, Macassar, Black, Nicaragua, Royale, Connecticut, Rubicon), cuatro ediciones limitadas (Spectre, Weller, Serie M, C8) y tres líneas retiradas. Cigar Coop escribe en agosto de 2026 que STG transfirió la marca de General Cigar Company a Forged Cigar Company, otra filial del grupo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El resultado práctico: Estados Unidos es el único mercado del mundo donde dos marcas completamente distintas llevan el nombre Cohiba. La versión estadounidense de General Cigar emplea tabaco dominicano y hondureño. Su perfil —más suave, más accesible, centrado en la regularidad— difiere radicalmente de la versión cubana. Ambas conviven legal y comercialmente desde hace décadas, para confusión duradera de los aficionados no avisados.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Eine amerikanische Cohiba wird außerhalb Kubas hergestellt: die Red Dot, die Blue und die Macassar in der Dominikanischen Republik (die Blue bei General Cigar Dominicana in Santiago), die Nicaragua und die Riviera in Nicaragua bei STG Estelí, die Royale und die Rubicon in Honduras sowie die Serie M in Miami bei El Titan de Bronze. Die Internetseite cohiba.com, die 2026 das Copyright von Forged Cigar Co., Inc. trägt, führt neun dauerhafte Linien auf (Red Dot, Riviera, Blue, Macassar, Black, Nicaragua, Royale, Connecticut, Rubicon), vier limitierte Editionen (Spectre, Weller, Serie M, C8) und drei eingestellte Linien. Cigar Coop schreibt im August 2026, STG habe die Marke von General Cigar Company auf Forged Cigar Company übertragen, eine weitere Tochtergesellschaft des Konzerns.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Das praktische Ergebnis: Die Vereinigten Staaten sind der einzige Markt der Welt, auf dem zwei völlig verschiedene Marken den Namen Cohiba tragen. Die amerikanische Version von General Cigar verwendet dominikanischen und honduranischen Tabak. Ihr Profil — milder, zugänglicher, auf Gleichmäßigkeit ausgerichtet — unterscheidet sich grundlegend von der kubanischen Version. Beide bestehen seit Jahrzehnten rechtlich und kommerziell nebeneinander, zur anhaltenden Verwirrung nicht eingeweihter Liebhaber.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('美国的 Cohiba 在古巴境外制造：Red Dot、Blue 与 Macassar 在多米尼加共和国制造（Blue 在圣地亚哥的 General Cigar Dominicana），Nicaragua 与 Riviera 在尼加拉瓜的 STG Estelí 制造，Royale 与 Rubicon 在洪都拉斯制造，Serie M 则在迈阿密的 El Titan de Bronze 制造。cohiba.com 网站在 2026年标注的版权所有者为 Forged Cigar Co., Inc.，列出九个常设产品线（Red Dot、Riviera、Blue、Macassar、Black、Nicaragua、Royale、Connecticut、Rubicon）、四款限量版（Spectre、Weller、Serie M、C8）和三个已停产的产品线。Cigar Coop 在 2026年8月写道，STG 已将该品牌从 General Cigar Company 转移至集团旗下的另一家子公司 Forged Cigar Company。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Cohiba USA'
UNION ALL SELECT 'Cohiba USA', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('实际结果是：美国是全世界唯一一个由两个截然不同的品牌共用 Cohiba 之名的市场。General Cigar 的美国版使用多米尼加与洪都拉斯烟叶，其风格更柔和、更易入口、以稳定一致见长，与古巴版大相径庭。两者在法律与商业上并存了数十年，也让不明就里的爱好者长期困惑。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Cohiba USA'
