UNION ALL SELECT 'Davidoff', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Selon la chronologie de la maison, sa famille quitta Kiev en 1911 pour s''installer à Genève, où son père, Henri Davidoff, ouvrit sa première boutique de tabac.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Son père Henrion avait fui les pogroms russes et gagné Genève en 1911, avec le savoir-faire d''un marchand de tabac de Kiev et la détermination d''en faire quelque chose. La boutique familiale de la rue de Rive devint l''une des adresses les plus respectées de la ville, un lieu où les acheteurs sérieux venaient chercher un conseil sérieux. Zino apprit le métier dès l''enfance, et y absorba quelque chose de plus important encore : qu''une expertise du tabac ne vaut rien si l''on ne sait pas la transmettre.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('According to the house''s chronology, his family left Kiev in 1911 to settle in Geneva, where his father, Henri Davidoff, opened his first tobacco shop.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('His father Henrion had fled the Russian pogroms, arriving in Geneva in 1911 with the skills of a Kiev tobacco merchant and the immigrant''s determination to make them count. The family shop on Rue de Rive became one of Geneva''s most respected specialty tobacconists — a place where serious buyers sought serious guidance. Zino learned the trade from childhood and absorbed something more important: that tobacco expertise was meaningless without the ability to communicate it.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Según la cronología de la casa, su familia dejó Kiev en 1911 para instalarse en Ginebra, donde su padre, Henri Davidoff, abrió su primera tienda de tabaco.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Su padre Henrion había huido de los pogromos rusos y alcanzado Ginebra en 1911, con el oficio de un comerciante de tabaco de Kiev y la determinación de hacer algo con él. La tienda familiar de la rue de Rive se convirtió en una de las direcciones más respetadas de la ciudad, un lugar donde los compradores serios iban a buscar un consejo serio. Zino aprendió el oficio desde la infancia, y absorbió allí algo aún más importante: que una pericia sobre el tabaco no vale nada si uno no sabe transmitirla.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Laut der Chronologie des Hauses verließ seine Familie 1911 Kiew, um sich in Genf niederzulassen, wo sein Vater Henri Davidoff sein erstes Tabakgeschäft eröffnete.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Sein Vater Henrion war den russischen Pogromen entkommen und 1911 nach Genf gelangt, mit dem Können eines Tabakhändlers aus Kiew und der Entschlossenheit, etwas daraus zu machen. Der Familienladen an der rue de Rive wurde zu einer der angesehensten Adressen der Stadt, einem Ort, an dem ernsthafte Käufer ernsthaften Rat suchten. Zino lernte das Fach von Kindheit an und nahm dort etwas noch Wichtigeres auf: dass Sachkenntnis über Tabak nichts wert ist, wenn man sie nicht weiterzugeben versteht.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('据该公司的年表，他一家于1911年离开基辅，迁居日内瓦，他的父亲亨利·大卫杜夫在那里开设了自己的首家烟草店。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('他的父亲亨里翁躲开俄国的排犹迫害，于1911年抵达日内瓦，带着一个基辅烟草商的本事，也带着把它做出点名堂的决心。里夫街上的家族店铺成了城里最受敬重的地址之一，认真的买家会去那里求一份认真的建议。齐诺从小学这门手艺，也在那里吸收了更要紧的一件事：关于烟草的见识，若不懂得传授，便一文不值。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('وبحسب التسلسل الزمني للدار، غادرت عائلته كييف عام 1911 لتستقرّ في جنيف، حيث افتتح أبوه هنري دافيدوف أول متجر له للتبغ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('كان أبوه هنريون قد فرّ من المذابح الروسية وبلغ جنيف عام 1911، ومعه حرفة تاجر تبغ من كييف وعزمٌ على أن يصنع منها شيئًا. وصار متجر العائلة في شارع ريف من أكثر عناوين المدينة احترامًا، مكانًا يقصده المشترون الجادّون طلبًا لمشورة جادّة. تعلّم زينو المهنة منذ الطفولة، وامتصّ فيها ما هو أهمّ: أنّ الخبرة بالتبغ لا تساوي شيئًا إن لم يُحسن صاحبها نقلها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('En 1968, la maison date la naissance de la marque de cigares Davidoff : les premiers cigares à bague blanche, créés à Cuba par Zino Davidoff, sortent cette année-là ; selon Wikipédia, c''est Cubatabaco qui avait approché Davidoff en 1967 avec une proposition, et les trois premiers vitolas datent de 1968-1969. En 1970, le groupe Oettinger reprend la boutique genevoise de Zino Davidoff, et Ernst Schneider, qui dirige le groupe depuis 1961, entreprend d''en faire une marque internationale.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('En 1968, il lança sous son propre nom la gamme qui allait transformer la culture européenne du cigare. Son génie fut commercial autant que tabacole : il convainquit le monopole cubain de produire des assemblages exclusifs portant le nom Davidoff, à des prix et dans des emballages qui les plaçaient délibérément à part. « Davidoff de La Havane » fut, pendant vingt-deux ans, l''objet de désir de qui prétendait savoir ce qu''est un cigare.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The house dates the birth of the Davidoff cigar brand to 1968: the first white-band cigars, created in Cuba by Zino Davidoff, came out that year; according to Wikipedia, it was Cubatabaco that had approached Davidoff in 1967 with a proposal, and the first three vitolas date from 1968-1969. In 1970, the Oettinger group took over Zino Davidoff''s Geneva shop, and Ernst Schneider, who had led the group since 1961, set about making it an international brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('In 1968, he launched under his own name the range that would transform European cigar culture. His commercial genius was specific: he convinced the Cuban tobacco monopoly to produce exclusive blends bearing the Davidoff name, at price points and in packaging that deliberately set them apart. ''Davidoff de La Havane'' became, for 22 years, the object of desire for anyone who understood what a cigar was supposed to be and was willing to pay accordingly.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La casa fecha el nacimiento de la marca de puros Davidoff en 1968: los primeros puros con anilla blanca, creados en Cuba por Zino Davidoff, salieron ese año; según Wikipedia, fue Cubatabaco quien se había acercado a Davidoff en 1967 con una propuesta, y las tres primeras vitolas datan de 1968-1969. En 1970, el grupo Oettinger se hizo cargo de la tienda ginebrina de Zino Davidoff, y Ernst Schneider, que dirigía el grupo desde 1961, emprendió la tarea de convertirla en una marca internacional.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('En 1968 lanzó bajo su propio nombre la gama que iba a transformar la cultura europea del puro. Su genio fue comercial tanto como tabaquero: convenció al monopolio cubano de producir ligadas exclusivas con el nombre Davidoff, a precios y en embalajes que las situaban deliberadamente aparte. «Davidoff de La Habana» fue, durante veintidós años, el objeto de deseo de quien pretendía saber lo que es un puro.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Haus datiert die Geburt der Zigarrenmarke Davidoff auf das Jahr 1968: Die ersten Zigarren mit weißer Bauchbinde, von Zino Davidoff auf Kuba geschaffen, erschienen in diesem Jahr; laut Wikipedia war es Cubatabaco, das Davidoff 1967 mit einem Vorschlag angesprochen hatte, und die ersten drei Vitolas stammen aus den Jahren 1968-1969. 1970 übernahm die Oettinger-Gruppe das Genfer Geschäft von Zino Davidoff, und Ernst Schneider, der die Gruppe seit 1961 leitete, machte sich daran, daraus eine internationale Marke zu machen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1968 brachte er unter eigenem Namen die Linie heraus, die die europäische Zigarrenkultur verändern sollte. Sein Einfall war kaufmännisch ebenso wie tabaklich: Er überzeugte das kubanische Monopol, ausschließliche Mischungen unter dem Namen Davidoff herzustellen, zu Preisen und in Verpackungen, die sie mit Absicht abseits stellten. «Davidoff de La Havane» war zweiundzwanzig Jahre lang der Gegenstand der Begierde all jener, die zu wissen vorgaben, was eine Zigarre ist.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('该公司将 Davidoff 雪茄品牌的诞生定在1968年：由齐诺·大卫杜夫在古巴创制的首批白色烟标雪茄于当年面世；据维基百科，是 Cubatabaco 于1967年带着一项提议接触了 Davidoff，而前三款 vitola 的年份为1968-1969年。1970年，Oettinger 集团接手了齐诺·大卫杜夫在日内瓦的店铺，自1961年起执掌该集团的 Ernst Schneider 着手把它打造成一个国际品牌。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('1968年，他以自己的名字推出了那条将改变欧洲雪茄文化的产品线。他的过人之处在商业，也在烟草：他说服古巴的专营机构生产冠以大卫杜夫之名的专属配方，其定价与包装都刻意把它们放在另一个层级。在长达二十二年里，「哈瓦那大卫杜夫」是所有自认懂雪茄之人的欲望之物。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تؤرّخ الدار ميلاد علامة سيجار Davidoff بعام 1968: ففي ذلك العام خرج أول سيجار بحلقة بيضاء ابتكره زينو دافيدوف في كوبا؛ وبحسب ويكيبيديا فإن Cubatabaco هي التي اتصلت بـ Davidoff في 1967 بعرض، وتعود الـvitolas الثلاث الأولى إلى 1968-1969. وفي 1970 تولّت مجموعة Oettinger متجر زينو دافيدوف في جنيف، وشرع Ernst Schneider، الذي كان يدير المجموعة منذ 1961، في جعله علامة دولية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('وفي 1968 أطلق باسمه هو التشكيلة التي ستغيّر ثقافة السيجار الأوروبية. كانت عبقريته تجارية بقدر ما كانت تبغية: فقد أقنع الاحتكار الكوبي بإنتاج خلطات حصرية تحمل اسم دافيدوف، بأسعار وأغلفة تضعها عمدًا على حدة. وظلّ «دافيدوف دي لا هافانا» اثنتين وعشرين سنة موضع رغبة كل من ادّعى معرفة ما هو السيجار.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Depuis 1991, dit la maison, tous les cigares Davidoff sont roulés à la main en République dominicaine, à Villa González (Santiago), où sont aussi fabriqués AVO, The Griffin''s, Cusano, Private Stock et Zino Platinum. Sur la rupture avec Cuba, les pages divergent. Selon la presse du métier, Zino Davidoff mit le feu en 1989, avec des représentants de Cubatabaco et des douaniers suisses, à environ 130 000 cigares havanais ; après des différends avec Cubatabaco et des problèmes de tirage et de combustion, la production de Davidoff à Cuba cessa en 1991, un accord prévoyant d''écouler le stock restant avant fin 1992. Wikipédia écrit que Zino Davidoff et Cubatabaco ont décidé ensemble de mettre fin à leur relation après de nombreux différends sur la qualité et les droits, et que la rupture fut formalisée en 1990-1991 ; le détaillant Holt''s écrit qu''en 1991 Zino avait dissous la relation et déplacé toute la production en République dominicaine, en invoquant la perte du contrôle qualité. La chronologie de la maison ne date que le roulage dominicain, à partir de 1991.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La rupture de 1990 fit l''effet d''un séisme. Davidoff s''inquiétait depuis quelque temps de la régularité de la production havanaise — des feuilles qui ne correspondaient pas aux spécifications, des cigares au tirage difficile, des lots qui variaient trop d''une boîte à l''autre. Les négociations privées ayant échoué, Zino annonça publiquement qu''il mettait fin à la relation cubaine et transférait sa production en République dominicaine.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Since 1991, says the house, all Davidoff cigars have been hand-rolled in the Dominican Republic, at Villa González (Santiago), where AVO, The Griffin''s, Cusano, Private Stock and Zino Platinum are also made. On the break with Cuba, the pages differ. According to the trade press, Zino Davidoff set fire in 1989, together with representatives of Cubatabaco and Swiss customs officers, to about 130 000 Havana cigars; after disputes with Cubatabaco and problems of draw and combustion, Davidoff''s production in Cuba ceased in 1991, with an agreement providing for the remaining stock to be sold off before the end of 1992. Wikipedia writes that Zino Davidoff and Cubatabaco jointly decided to end their relationship after numerous disputes over quality and rights, and that the break was formalised in 1990-1991; the retailer Holt''s writes that in 1991 Zino had dissolved the relationship and moved all production to the Dominican Republic, citing the loss of quality control. The house''s chronology dates only the Dominican rolling, from 1991 on.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The rupture of 1990 was the most dramatic event in modern cigar history. Davidoff had grown increasingly concerned about the consistency of Havana''s production — leaves arriving that did not match specifications, cigars with draw problems, batches that varied unacceptably from one box to the next. After private negotiations failed to resolve the situation, Zino announced publicly that Davidoff was ending its Cuban relationship and transferring production to the Dominican Republic.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Desde 1991, dice la casa, todos los puros Davidoff se enrollan a mano en República Dominicana, en Villa González (Santiago), donde también se fabrican AVO, The Griffin''s, Cusano, Private Stock y Zino Platinum. Sobre la ruptura con Cuba, las páginas divergen. Según la prensa del sector, Zino Davidoff prendió fuego en 1989, junto con representantes de Cubatabaco y aduaneros suizos, a unos 130 000 puros habaneros; tras desacuerdos con Cubatabaco y problemas de tiro y de combustión, la producción de Davidoff en Cuba cesó en 1991, con un acuerdo que preveía dar salida a las existencias restantes antes de finales de 1992. Wikipedia escribe que Zino Davidoff y Cubatabaco decidieron juntos poner fin a su relación tras numerosos desacuerdos sobre la calidad y los derechos, y que la ruptura se formalizó en 1990-1991; el minorista Holt''s escribe que en 1991 Zino había disuelto la relación y trasladado toda la producción a República Dominicana, alegando la pérdida del control de calidad. La cronología de la casa solo fecha el enrollado dominicano, a partir de 1991.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La ruptura de 1990 tuvo el efecto de un terremoto. Davidoff se inquietaba desde hacía tiempo por la regularidad de la producción habanera —hojas que no correspondían a las especificaciones, puros de tiro difícil, lotes que variaban demasiado de una caja a otra. Fracasadas las negociaciones privadas, Zino anunció públicamente que ponía fin a la relación cubana y trasladaba su producción a República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Seit 1991, so das Haus, werden alle Davidoff-Zigarren in der Dominikanischen Republik von Hand gerollt, in Villa González (Santiago), wo auch AVO, The Griffin''s, Cusano, Private Stock und Zino Platinum hergestellt werden. Zum Bruch mit Kuba gehen die Seiten auseinander. Laut der Fachpresse zündete Zino Davidoff 1989 gemeinsam mit Vertretern von Cubatabaco und Schweizer Zollbeamten rund 130 000 Havanna-Zigarren an; nach Differenzen mit Cubatabaco sowie Problemen mit Zug und Abbrand endete Davidoffs Produktion auf Kuba 1991, wobei eine Vereinbarung vorsah, den verbliebenen Bestand vor Ende 1992 abzusetzen. Wikipedia schreibt, Zino Davidoff und Cubatabaco hätten gemeinsam beschlossen, ihre Beziehung nach zahlreichen Differenzen über Qualität und Rechte zu beenden, und der Bruch sei 1990-1991 formalisiert worden; der Händler Holt''s schreibt, Zino habe 1991 die Beziehung aufgelöst und die gesamte Produktion in die Dominikanische Republik verlegt, unter Verweis auf den Verlust der Qualitätskontrolle. Die Chronologie des Hauses datiert nur das dominikanische Rollen, ab 1991.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Der Bruch von 1990 wirkte wie ein Beben. Davidoff sorgte sich seit einiger Zeit um die Gleichmäßigkeit der havannesischen Produktion — Blätter, die den Vorgaben nicht entsprachen, Zigarren mit schwerem Zug, Partien, die von Kiste zu Kiste zu sehr schwankten. Nachdem die vertraulichen Verhandlungen gescheitert waren, gab Zino öffentlich bekannt, dass er die kubanische Beziehung beende und seine Produktion in die Dominikanische Republik verlege.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('据该公司称，自1991年起，所有 Davidoff 雪茄都在多米尼加共和国的 Villa González（Santiago）手工卷制，该地也生产 AVO、The Griffin''s、Cusano、Private Stock 和 Zino Platinum。关于与古巴的决裂，各页说法不一。据行业媒体，齐诺·大卫杜夫于1989年与 Cubatabaco 的代表和瑞士海关人员一起，焚烧了约 130 000 支哈瓦那雪茄；在与 Cubatabaco 发生分歧、并出现通气和燃烧方面的问题之后，Davidoff 在古巴的生产于1991年停止，一项协议规定在1992年底前售出剩余库存。维基百科写道，齐诺·大卫杜夫与 Cubatabaco 在质量和权利方面诸多分歧之后共同决定终止双方关系，决裂于1990-1991年正式确定；零售商 Holt''s 写道，1991年齐诺已解除这一关系，并将全部生产迁往多米尼加共和国，理由是失去了质量控制。该公司的年表只为多米尼加的卷制定了年份，自1991年起。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('1990年的决裂如同一场地震。此前一段时间，大卫杜夫已在担心哈瓦那生产的稳定性——不合规格的叶子、通气吃力的雪茄、一箱与一箱之间差异过大的批次。私下谈判失败之后，齐诺公开宣布终止与古巴的关系，把生产迁往多米尼加共和国。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('منذ 1991، تقول الدار، يُلَفّ كل سيجار Davidoff يدويًا في الجمهورية الدومينيكية، في Villa González (Santiago)، حيث تُصنع أيضًا AVO وThe Griffin''s وCusano وPrivate Stock وZino Platinum. وبشأن الانفصال عن كوبا، تتباين الصفحات. فبحسب صحافة القطاع، أحرق زينو دافيدوف في 1989، مع ممثلين عن Cubatabaco ورجال جمارك سويسريين، نحو 130 000 سيجار هافاني؛ وبعد خلافات مع Cubatabaco ومشكلات في السحب والاحتراق، توقّف إنتاج Davidoff في كوبا عام 1991، مع اتفاق ينص على تصريف المخزون المتبقي قبل نهاية 1992. وتكتب ويكيبيديا أن زينو دافيدوف وCubatabaco قرّرا معًا إنهاء علاقتهما بعد خلافات كثيرة حول الجودة والحقوق، وأن الانفصال أُضفي عليه طابع رسمي في 1990-1991؛ ويكتب تاجر التجزئة Holt''s أن زينو كان قد فسخ العلاقة في 1991 ونقل الإنتاج كله إلى الجمهورية الدومينيكية، محتجًّا بفقدان مراقبة الجودة. ولا تؤرّخ الدار في تسلسلها الزمني إلا اللفّ الدومينيكي، ابتداءً من 1991.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وكان انفصال 1990 أشبه بزلزال. فقد كان القلق يساور دافيدوف منذ حين بشأن انتظام الإنتاج الهافاني — أوراق لا تطابق المواصفات، وسيجار عسير السحب، ودفعات تتفاوت أكثر مما ينبغي من علبة إلى أخرى. ولمّا أخفقت المفاوضات الخاصة، أعلن زينو علنًا إنهاء العلاقة الكوبية ونقل إنتاجه إلى الجمهورية الدومينيكية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Le catalogue s''élargit ensuite : le groupe acquiert en 2007 les droits exclusifs sur le nom Winston Churchill pour un cigare, et la ligne est lancée en mai 2008 ; Davidoff Nicaragua, sous une bague noire, sort en 2013 ; Yamasá, troisième Davidoff à bague noire avec cape et sous-cape dominicaines, en 2016.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Le monde du cigare en resta sidéré. Les Davidoff cubains d''époque — que des collectionneurs pressentant la suite avaient déjà mis en cave — prirent aussitôt de la valeur. Ils comptent aujourd''hui parmi les pièces les plus recherchées du marché secondaire, vendues en ventes spécialisées à des prix qui disent la fin d''une époque.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('The catalogue then widened: in 2007 the group acquired the exclusive rights to the name Winston Churchill for a cigar, and the line was launched in May 2008; Davidoff Nicaragua, under a black band, came out in 2013; Yamasá, the third black-band Davidoff, with Dominican wrapper and binder, in 2016.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The cigar world was stunned. Vintage Cuban Davidoffs — already accumulated in cellars by collectors who sensed what was coming — became immediately valuable. They are today among the most prized collectibles in the secondary market, sold at specialist auctions at prices that reflect their status as the end of an era.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('El catálogo se amplió después: el grupo adquirió en 2007 los derechos exclusivos sobre el nombre Winston Churchill para un puro, y la línea se lanzó en mayo de 2008; Davidoff Nicaragua, bajo una anilla negra, salió en 2013; Yamasá, tercer Davidoff de anilla negra con capa y capote dominicanos, en 2016.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('El mundo del puro quedó estupefacto. Los Davidoff cubanos de época —que algunos coleccionistas, presintiendo lo que venía, ya habían puesto en cava— tomaron valor en el acto. Hoy se cuentan entre las piezas más buscadas del mercado secundario, vendidas en subastas especializadas a precios que dicen el final de una época.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Das Sortiment wuchs danach: Die Gruppe erwarb 2007 die exklusiven Rechte am Namen Winston Churchill für eine Zigarre, und die Linie wurde im Mai 2008 lanciert; Davidoff Nicaragua erschien 2013 unter einer schwarzen Bauchbinde; Yamasá, der dritte Davidoff mit schwarzer Bauchbinde und dominikanischem Deck- und Umblatt, 2016.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die Zigarrenwelt war fassungslos. Die kubanischen Davidoff jener Zeit — die manche Sammler, die das Kommende ahnten, bereits eingelagert hatten — gewannen sofort an Wert. Sie zählen heute zu den gesuchtesten Stücken des Zweitmarkts und werden in Fachauktionen zu Preisen verkauft, die das Ende einer Epoche aussprechen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('此后产品目录继续扩大：该集团于2007年取得 Winston Churchill 之名用于雪茄的独家权利，该系列于2008年5月推出；Davidoff Nicaragua 使用黑色烟标，于2013年问世；Yamasá 是第三款黑色烟标的 Davidoff，茄衣和茄套均为多米尼加产，于2016年推出。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('雪茄界为之愕然。那些年份的古巴大卫杜夫——一些预感到后事的收藏者早已入柜——立刻涨了价。如今它们属于二级市场上最被追逐的物件之列，在专场拍卖中以那种宣告一个时代结束的价格成交。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('ثم اتّسع الكتالوج: فقد استحوذت المجموعة في 2007 على الحقوق الحصرية لاسم Winston Churchill لسيجار، وأُطلق الخط في مايو 2008؛ وصدر Davidoff Nicaragua تحت حلقة سوداء في 2013؛ وصدر Yamasá، ثالث سيجار Davidoff بحلقة سوداء، بغلاف خارجي ورابط دومينيكيين، في 2016.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('ذُهل عالم السيجار. أما سيجار دافيدوف الكوبي من تلك الحقبة — الذي كان جامعون استشعروا ما هو آتٍ قد خزّنوه بالفعل — فارتفعت قيمته على الفور. وهو اليوم من أكثر القطع طلبًا في السوق الثانوية، ويُباع في مزادات متخصّصة بأسعار تنطق بنهاية عهد.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 5 (nouveau texte)', (LOCATE(CAST('En 2021, la maison fête trente ans de production dominicaine (1991-2021), qu''elle associe au début de sa philosophie « Crop-to-Shop » ; en 2025, l''extension du site doit permettre de doubler la production annuelle de cigares roulés à la main et comprend un centre d''assemblage de 1 700 m².' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'fr', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Les Davidoff dominicains sont d''autres cigares. Plus doux, plus floraux, d''un accès plus immédiat que les cubains d''origine, ils portent l''argument de la maison : le tabac dominicain, choisi et assemblé avec la rigueur que Zino appliquait à ses relations cubaines, peut produire des cigares d''une sophistication équivalente. Le marché a largement accepté cet argument.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 5 (nouveau texte)', (LOCATE(CAST('In 2021 the house celebrated thirty years of Dominican production (1991-2021), which it associates with the start of its ''Crop-to-Shop'' philosophy; in 2025, the extension of the site is meant to double the annual production of hand-rolled cigars, and includes a 1 700 m² blending centre.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'en', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Dominican Davidoffs are different cigars. Softer, more floral, more immediately accessible than the Cuban originals, they represent the house''s argument that Dominican tobacco, selected and blended with the same rigor that Zino applied to his Cuban relationships, can produce cigars of equivalent sophistication. The market has largely accepted that argument. The Davidoff Millennium Blend, the Signature, and the Year of the series carry that argument in the market today.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 5 (nouveau texte)', (LOCATE(CAST('En 2021, la casa celebró treinta años de producción dominicana (1991-2021), que asocia al inicio de su filosofía «Crop-to-Shop»; en 2025, la ampliación del sitio debe permitir duplicar la producción anual de puros enrollados a mano e incluye un centro de ligado de 1 700 m².' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'es', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Los Davidoff dominicanos son otros puros. Más suaves, más florales, de acceso más inmediato que los cubanos de origen, llevan el argumento de la casa: el tabaco dominicano, escogido y ligado con el rigor que Zino aplicaba a sus relaciones cubanas, puede producir puros de una sofisticación equivalente. El mercado ha aceptado ampliamente ese argumento.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 5 (nouveau texte)', (LOCATE(CAST('2021 feierte das Haus dreißig Jahre dominikanische Produktion (1991-2021), die es mit dem Beginn seiner Philosophie «Crop-to-Shop» verbindet; 2025 soll die Erweiterung des Standorts es ermöglichen, die jährliche Produktion handgerollter Zigarren zu verdoppeln, und umfasst ein Mischzentrum von 1 700 m².' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'de', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('Die dominikanischen Davidoff sind andere Zigarren. Milder, blumiger, unmittelbarer zugänglich als die ursprünglichen kubanischen, tragen sie das Argument des Hauses: Dominikanischer Tabak, mit der Strenge ausgewählt und gemischt, die Zino auf seine kubanischen Beziehungen anwandte, kann Zigarren von gleichwertiger Verfeinerung hervorbringen. Der Markt hat dieses Argument weithin angenommen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 5 (nouveau texte)', (LOCATE(CAST('2021年，该公司庆祝了多米尼加生产三十周年（1991-2021年），并将其与「Crop-to-Shop」理念的起点联系在一起；2025年，厂区扩建应能使手工卷制雪茄的年产量翻倍，并包含一个1 700平方米的拼配中心。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'zh', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('多米尼加的大卫杜夫是另一种雪茄。比原来的古巴款更柔和、更带花香、更易入口，它们承载着这家字号的论点：多米尼加烟草，若以齐诺对待古巴合作时的严格去挑选与配比，同样能造出等量级的精致。市场大体上接受了这个论点。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('وفي 2021 احتفلت الدار بثلاثين عامًا من الإنتاج الدومينيكي (1991-2021)، وتربطها ببداية فلسفتها «Crop-to-Shop»؛ وفي 2025 يُفترض أن يتيح توسيع الموقع مضاعفة الإنتاج السنوي من السيجار الملفوف يدويًا، ويضمّ مركزًا للتوليف مساحته 1 700 متر مربع.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Davidoff'
UNION ALL SELECT 'Davidoff', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وسيجار دافيدوف الدومينيكي سيجار آخر. ألطف، وأكثر زهرية، وأيسر تناولًا من الكوبي الأصلي، وهو يحمل حجّة الدار: أنّ التبغ الدومينيكي، إذا انتُقي وخُلط بالصرامة التي طبّقها زينو على علاقاته الكوبية، قادر على إنتاج سيجار من رهافة مكافئة. وقد قبلت السوق هذه الحجّة على نطاق واسع.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Davidoff'
