UNION ALL SELECT 'Davidoff', 'zh', 'gamme Signature (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_zh`, '$[0].story')) AS BINARY) = CAST('White Band Collection 系列中的一款。Signature 2000 是一款环径43、长12.9厘米的 corona，1976年出现在 Mille Series 中（zigarren.zone，2026年2月12日）；2026年是它的五十周年，有五种包装带有周年贴纸，据该公司称。关于这款 Signature 2000，该公司给出的烟叶来自多米尼加共和国和厄瓜多尔，并称其在自家五级量表上的强度为1.5；茄衣来自厄瓜多尔，茄套和茄芯来自多米尼加共和国，据 zigarren.zone（CigarSense 则写作厄瓜多尔杂交茄套）。于 Villa González（Santiago）手工卷制，与1991年以来所有的 Davidoff 一样，据该公司称。Aniversario 是 White Band Collection 中另成一体的系列，于1986年为庆祝齐诺·大卫杜夫的80岁生日而推出。' AS BINARY)) FROM `brands` WHERE `name` = 'Davidoff'
