UNION ALL SELECT 'Davidoff', 'ar', 'gamme Nicaragua (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_ar`, '$[2].story')) AS BINARY) = CAST('أُطلقت عام 2013 تحت حلقة سوداء، تقول الدار، ويوضّح مدخلها أن Davidoff علامة تجارية وليست إقليمًا. وتجمع نسخة Box Pressed، المعلن عنها في فبراير 2016 (Cigar Coop، 22 فبراير 2016)، بين غلاف خارجي Habana Oscuro من نيكاراغوا، ورابط Habana Jalapa، وحشوة من Ometepe وCondega وEstelí، مع قطفة ligero معزَّزة؛ بمقاسي Robusto 5 x 48 وToro 6 x 52. ويصف متجر الدار Toro المكبوس في العلبة بأنه مصنوع من تبغ نيكاراغوي 100 %، وشدّته 4.5 من 5 على مقياسها. وتذكر Cigar Coop الجمهورية الدومينيكية (Tabadom) بلدًا للّف، وهو ما يتوافق مع التسلسل الزمني للدار (كل سيجار Davidoff يُلَفّ في Villa González منذ 1991).' AS BINARY)) FROM `brands` WHERE `name` = 'Davidoff'
