UNION ALL SELECT 'Davidoff', 'fr', 'gamme Back2Back (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme`, '$[3].story')) AS BINARY) = CAST('Reprise du Room101 Big Payback : d''après Cigar Coop (27 juillet 2018), Back2Back en est la réincarnation, Matt Booth ayant gardé les noms de Room101 et Davidoff les assemblages ; les artistes new-yorkais UR NY (Fernando Romero et Mike Baca) signent les boîtes. Lancée par Davidoff à l''IPCPR de juillet 2018 selon Cigar Coop ; sortie en octobre 2018 selon Corona Cigar Co. et Blind Man''s Puff (17 juillet 2020), qui la rangent en force légère à moyenne. Deux versions, Connecticut (cape Connecticut Shade d''Équateur, liant mexicain, tripe dominicaine) et Nicaragua (puro), en 5 x 50, 6 x 60 et 7 x 70. Roulées à la main au Honduras, chez Diadema Cigars de Honduras selon Cigar Coop (2018) ; Blind Man''s Puff (2020) donne Tabadom comme usine. Une édition limitée 2019 a été présentée à l''IPCPR en juillet 2019 (Cigar Coop). En octobre 2026, la ligne ne figure pas sur la page marque de davidoff.com.' AS BINARY)) FROM `brands` WHERE `name` = 'Davidoff'
