UNION ALL SELECT 'Oettinger Davidoff', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('À Genève, la famille Davidoff arrive de Kiev en 1911 et Henri Davidoff y ouvre sa première boutique de tabac. Les premiers cigares à bague blanche, créés à Cuba par Zino Davidoff, sortent en 1968 ; en 1970, le groupe Oettinger reprend la boutique genevoise de Zino Davidoff, et Ernst Schneider, qui en dirige le groupe depuis 1961, entreprend d''en faire une marque internationale.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Zino Davidoff, lui, reprend en 1930 la boutique de son père à Genève et en fait une maison. En 1970, il vend son affaire à Max Oettinger : les deux noms n''en font plus qu''un.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('In Geneva, the Davidoff family arrived from Kiev in 1911 and Henri Davidoff opened his first tobacco shop there. The first white-band cigars, created in Cuba by Zino Davidoff, came out in 1968; in 1970, the Oettinger group took over Zino Davidoff''s Geneva shop, and Ernst Schneider, who had led the group since 1961, set about making it an international brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Zino Davidoff, for his part, took over his father''s Geneva shop in 1930 and turned it into a house. In 1970 he sold his business to Max Oettinger: the two names became one.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('En Ginebra, la familia Davidoff llega de Kiev en 1911 y Henri Davidoff abre allí su primera tienda de tabaco. Los primeros puros con anilla blanca, creados en Cuba por Zino Davidoff, salen en 1968; en 1970, el grupo Oettinger se hace cargo de la tienda ginebrina de Zino Davidoff, y Ernst Schneider, que dirige el grupo desde 1961, emprende la tarea de convertirla en una marca internacional.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Zino Davidoff, por su parte, toma en 1930 la tienda de su padre en Ginebra y la convierte en una casa. En 1970 vende su negocio a Max Oettinger: los dos nombres pasan a ser uno.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('In Genf kam die Familie Davidoff 1911 aus Kiew an, und Henri Davidoff eröffnete dort sein erstes Tabakgeschäft. Die ersten Zigarren mit weißer Bauchbinde, von Zino Davidoff auf Kuba geschaffen, erschienen 1968; 1970 übernahm die Oettinger-Gruppe das Genfer Geschäft von Zino Davidoff, und Ernst Schneider, der die Gruppe seit 1961 leitete, machte sich daran, daraus eine internationale Marke zu machen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Zino Davidoff wiederum übernahm 1930 den Laden seines Vaters in Genf und machte daraus ein Haus. 1970 verkaufte er sein Geschäft an Max Oettinger: Aus zwei Namen wurde einer.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('在日内瓦，大卫杜夫一家于 1911年从基辅来到此地，亨利·大卫杜夫在那里开设了自己的首家烟草店。由齐诺·大卫杜夫在古巴创制的首批白色烟标雪茄于 1968年问世；1970年，Oettinger 集团接手了齐诺·大卫杜夫在日内瓦的店铺，自 1961年起执掌该集团的 Ernst Schneider 着手把它打造成一个国际品牌。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('至于齐诺·大卫杜夫，他于 1930 年接手父亲在日内瓦的店铺，并将其经营成一家名庄。1970 年，他把生意卖给了马克斯·厄廷格：两个名字自此合而为一。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('في جنيف، وصلت عائلة دافيدوف من كييف عام 1911، وافتتح هنري دافيدوف فيها أول متجر له للتبغ. وصدر عام 1968 أول سيجار بحلقة بيضاء ابتكره زينو دافيدوف في كوبا؛ وفي 1970 تولّت مجموعة Oettinger متجر زينو دافيدوف في جنيف، وشرع Ernst Schneider، الذي كان يدير المجموعة منذ 1961، في جعله علامة دولية.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('أمّا زينو دافيدوف فقد تسلّم عام 1930 متجر والده في جنيف وحوّله إلى دار. وفي 1970 باع عمله إلى ماكس أوتينغر، فصار الاسمان اسمًا واحدًا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Les rachats viennent ensuite : Camacho (Danlí, Honduras, et Miami) le 1er octobre 2008, qui apporte au groupe une seconde provenance, le Honduras, puis Cusano en 2009, qui lui ouvre de nouveaux circuits de distribution aux États-Unis. Depuis 1991, tous les Davidoff sont roulés à la main en République dominicaine, à Villa González (Santiago), où la maison fabrique aussi AVO, The Griffin''s, Cusano, Private Stock et Zino Platinum ; Zino, lancée en 1978 et alors roulée au Honduras, est relancée en 2021 avec un profil nicaraguayen. Le groupe reste familial ; il compte plus de 4 000 collaborateurs dans le monde (communiqué du 11 juin 2025), est dirigé par Beat Hauenstein, CEO depuis 2017, et a fêté ses 150 ans en mai 2025. Son siège, la Maison Davidoff, est au Nauenstrasse 73, à Bâle.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Le groupe reste familial. Il déclare environ cinq cents millions de francs suisses de ventes et près de quatre mille personnes dans le monde. L''atlas porte cinq de ses marques sans l''avoir jamais nommé : Davidoff, Avo, The Griffin''s, Camacho et Zino Platinum — auxquelles s''ajoutent Cusano, Private Stock et Zino.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The acquisitions came next: Camacho (Danlí, Honduras, and Miami) on 1 October 2008, which brought the group a second origin, Honduras, then Cusano in 2009, which opened new distribution channels for it in the United States. Since 1991, all Davidoff cigars have been hand-rolled in the Dominican Republic, at Villa González (Santiago), where the house also makes AVO, The Griffin''s, Cusano, Private Stock and Zino Platinum; Zino, launched in 1978 and then rolled in Honduras, was relaunched in 2021 with a Nicaraguan profile. The group remains family-owned; it has more than 4 000 employees worldwide (press release of 11 June 2025), is led by Beat Hauenstein, CEO since 2017, and celebrated 150 years in May 2025. Its headquarters, the Maison Davidoff, is at Nauenstrasse 73, in Basel.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The group remains family-owned. It reports around five hundred million Swiss francs in sales and close to four thousand people worldwide. This atlas holds five of its brands without ever having named it: Davidoff, Avo, The Griffin''s, Camacho and Zino Platinum — to which Cusano, Private Stock and Zino may be added.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Las compras vienen después: Camacho (Danlí, Honduras, y Miami) el 1 de octubre de 2008, que aporta al grupo una segunda procedencia, Honduras, y luego Cusano en 2009, que le abre nuevos circuitos de distribución en Estados Unidos. Desde 1991, todos los Davidoff se enrollan a mano en República Dominicana, en Villa González (Santiago), donde la casa fabrica también AVO, The Griffin''s, Cusano, Private Stock y Zino Platinum; Zino, lanzada en 1978 y entonces enrollada en Honduras, se relanza en 2021 con un perfil nicaragüense. El grupo sigue siendo familiar; cuenta con más de 4 000 colaboradores en el mundo (comunicado del 11 de junio de 2025), lo dirige Beat Hauenstein, CEO desde 2017, y celebró sus 150 años en mayo de 2025. Su sede, la Maison Davidoff, está en Nauenstrasse 73, en Basilea.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('El grupo sigue siendo familiar. Declara unos quinientos millones de francos suizos de ventas y cerca de cuatro mil personas en el mundo. Este atlas recoge cinco de sus marcas sin haberlo nombrado nunca: Davidoff, Avo, The Griffin''s, Camacho y Zino Platinum, a las que se añaden Cusano, Private Stock y Zino.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Die Übernahmen folgen danach: Camacho (Danlí, Honduras, und Miami) am 1. Oktober 2008, das der Gruppe eine zweite Herkunft, Honduras, einbringt, dann Cusano 2009, das ihr neue Vertriebswege in den Vereinigten Staaten eröffnet. Seit 1991 werden alle Davidoff in der Dominikanischen Republik von Hand gerollt, in Villa González (Santiago), wo das Haus auch AVO, The Griffin''s, Cusano, Private Stock und Zino Platinum herstellt; Zino, 1978 lanciert und damals in Honduras gerollt, wird 2021 mit nicaraguanischem Profil neu lanciert. Die Gruppe bleibt in Familienbesitz; sie zählt mehr als 4 000 Beschäftigte weltweit (Pressemitteilung vom 11. Juni 2025), wird von Beat Hauenstein geleitet, CEO seit 2017, und feierte im Mai 2025 ihr 150-jähriges Bestehen. Ihr Sitz, die Maison Davidoff, befindet sich an der Nauenstrasse 73 in Basel.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Gruppe bleibt in Familienbesitz. Sie weist rund fünfhundert Millionen Schweizer Franken Umsatz und knapp viertausend Beschäftigte weltweit aus. Dieser Atlas führt fünf ihrer Marken, ohne sie je genannt zu haben: Davidoff, Avo, The Griffin''s, Camacho und Zino Platinum — dazu kommen Cusano, Private Stock und Zino.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('收购随后而来：2008年10月1日收购 Camacho（洪都拉斯的 Danlí 与迈阿密），为集团带来第二个原产地洪都拉斯；2009年收购 Cusano，为其在美国打开新的分销渠道。自 1991年起，所有 Davidoff 均在多米尼加共和国的 Villa González（Santiago）手工卷制，该公司也在那里生产 AVO、The Griffin''s、Cusano、Private Stock 和 Zino Platinum；Zino 于 1978年推出，当时在洪都拉斯卷制，2021年以尼加拉瓜风格重新推出。该集团仍为家族所有；全球员工逾 4 000 人（2025年6月11日的新闻稿），由 2017年起任首席执行官的 Beat Hauenstein 领导，并于 2025年5月庆祝了 150 周年。其总部 Maison Davidoff 位于巴塞尔的 Nauenstrasse 73。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('该集团至今仍为家族所有，公布的销售额约为五亿瑞士法郎，全球员工近四千人。本图集收录了它旗下五个品牌，却从未提及它本身：Davidoff、Avo、The Griffin''s、Camacho 与 Zino Platinum，此外还有 Cusano、Private Stock 与 Zino。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('ثم جاءت عمليات الاستحواذ: Camacho (Danlí، هندوراس، وميامي) في 1 أكتوبر 2008، وقد منحت المجموعة منشأً ثانيًا هو هندوراس، ثم Cusano في 2009، التي فتحت لها قنوات توزيع جديدة في الولايات المتحدة. ومنذ 1991 يُلَفّ كل سيجار Davidoff يدويًا في الجمهورية الدومينيكية، في Villa González (Santiago)، حيث تصنع الدار أيضًا AVO وThe Griffin''s وCusano وPrivate Stock وZino Platinum؛ أما Zino، التي أُطلقت في 1978 وكانت تُلَفّ حينها في هندوراس، فأُعيد إطلاقها في 2021 بطابع نيكاراغوي. وتبقى المجموعة عائلية؛ ويعمل فيها ما يزيد على 4 000 موظف حول العالم (بيان صحفي بتاريخ 11 يونيو 2025)، ويديرها Beat Hauenstein، الرئيس التنفيذي منذ 2017، وقد احتفلت بمرور 150 عامًا في مايو 2025. ومقرّها، Maison Davidoff، في Nauenstrasse 73 ببازل.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('ولا تزال المجموعة عائلية، وتعلن نحو خمسمئة مليون فرنك سويسري من المبيعات وقرابة أربعة آلاف موظّف حول العالم. ويضمّ هذا الأطلس خمسًا من علاماتها دون أن يسمّيها قطّ: دافيدوف، وأفو، وذا غريفنز، وكاماتشو، وزينو بلاتينوم — يضاف إليها كوسانو وبرايفت ستوك وزينو.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
UNION ALL SELECT 'Oettinger Davidoff', 'fr', 'source (correction)', (LOCATE(CAST('oettingerdavidoff.com/history « History » (page consultée le 14 octobre 2026 : 1875 Eisengasse 9 ; 1911 la famille Davidoff à Genève ; 1961 Ernst Schneider prend la direction ; 1968 premiers cigares à bague blanche ; 1970 reprise de la boutique de Zino Davidoff ; 1978 Zino, roulée au Honduras ; 1991 production des Davidoff en République dominicaine, à Villa Gonzales (Santiago), où sont aussi fabriqués AVO, The Griffin''s, Cusano, Private Stock et Zino Platinum ; 2008 Camacho, Danlí, le 1er octobre ; 2009 Cusano ; 2017 Hauenstein CEO ; 2021 relance de Zino, profil nicaraguayen ; 2025 150 ans) ; oettingerdavidoff.com « Celebrating 150 Years of Excellence » (11 juin 2025 : fondation en mai 1875 à la Eisengasse 9, groupe familial, plus de 4 000 collaborateurs, CEO Beat Hauenstein, siège à Bâle, aucun chiffre de ventes) ; oettingerdavidoff.com (page d''accueil, consultée le 14 octobre 2026 : Maison Davidoff, Nauenstrasse 73, CH-4002 Bâle ; ni ventes ni effectifs chiffrés)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oettinger Davidoff'
