UNION ALL SELECT 'producer_countries cuba', 'es', 'notes', (CAST(`notes_es` AS BINARY) = CAST('Los puros habanos están protegidos por la Denominación de Origen Protegida Habanos, con un Consejo Regulador y un sello en cada caja desde 1994. Su tabaco procede de zonas de cultivo definidas: Vuelta Abajo, Semi Vuelta, Partido, Remedios. Se lían a mano en fábricas madre, sobre todo en La Habana.' AS BINARY)) FROM `producer_countries` WHERE `id` = 'cuba'
