UNION ALL SELECT 'producer_countries cuba', 'ar', 'notes', (CAST(`notes_ar` AS BINARY) = CAST('يحظى سيجار habano بحماية Denominación de Origen Protegida Habanos، مع مجلس تنظيمي وختم على كل علبة منذ 1994. يأتي تبغه من مناطق زراعة محددة: Vuelta Abajo وSemi Vuelta وPartido وRemedios. يُلفّ يدويًا في مصانع أمّ، ولا سيما في هافانا.' AS BINARY)) FROM `producer_countries` WHERE `id` = 'cuba'
