UNION ALL SELECT 'habanos_presence cuba', 'ar', 'ownership', (CAST(`ownership_ar` AS BINARY) = CAST('الدولة الكوبية (50٪) + Tabacalera SLU، مجموعة Allied Cigar Corporation S.L. (50٪، منذ 29 أكتوبر 2020)' AS BINARY)) FROM `habanos_presence` WHERE `country_id` = 'cuba'
UNION ALL SELECT 'habanos_presence cuba', 'fr', 'description', (CAST(`description` AS BINARY) = CAST('Habanos S.A., fondée en 1994, assure la promotion et la distribution internationales de 27 marques de cigares cubains roulés à la main, sur plus de 130 territoires (communiqué de février 2025). L''appellation d''origine protégée Habanos est régie par un Conseil régulateur ; le sceau Habanos figure sur chaque boîte depuis 1994.
