UNION ALL SELECT 'habanos_presence cuba', 'en', 'description', (CAST(`description_en` AS BINARY) = CAST('Habanos S.A., founded in 1994, handles the international promotion and distribution of 27 hand-rolled Cuban cigar brands in more than 130 territories (press release of February 2025). The protected designation of origin Habanos is governed by a Regulatory Council; the Habanos seal has appeared on every box since 1994.
