UNION ALL SELECT 'habanos_presence cuba', 'es', 'description', (CAST(`description_es` AS BINARY) = CAST('Habanos S.A., fundada en 1994, se encarga de la promoción y la distribución internacionales de 27 marcas de puros cubanos liados a mano, en más de 130 territorios (comunicado de febrero de 2025). La denominación de origen protegida Habanos está regida por un Consejo Regulador; el sello Habanos figura en cada caja desde 1994.
