UNION ALL SELECT 'habanos_presence cuba', 'de', 'description', (CAST(`description_de` AS BINARY) = CAST('Habanos S.A., 1994 gegründet, übernimmt die internationale Förderung und den Vertrieb von 27 Marken handgerollter kubanischer Zigarren in mehr als 130 Territorien (Pressemitteilung vom Februar 2025). Die geschützte Ursprungsbezeichnung Habanos wird von einem Regulierungsrat verwaltet; das Habanos-Siegel ist seit 1994 auf jeder Kiste angebracht.
Chen Zhi (Prince Group), am 14. Oktober 2025 von den Vereinigten Staaten und dem Vereinigten Königreich sanktioniert, soll laut Fachpresse (Juni 2026) 57,1 % von Allied Cigar Corporation halten; die Presse meldete im September 2026 keinen abgeschlossenen Verkauf dieses Anteils.' AS BINARY)) FROM `habanos_presence` WHERE `country_id` = 'cuba'
UNION ALL SELECT 'habanos_presence cuba', 'zh', 'description', (CAST(`description_zh` AS BINARY) = CAST('Habanos S.A. 成立于1994年，负责27个手工卷制的古巴雪茄品牌在130多个地区的国际推广与分销（2025年2月新闻稿）。受保护原产地名称 Habanos 由监管委员会管理；自1994年起，每个雪茄盒上都有 Habanos 印章。
Chen Zhi（Prince Group）于2025年10月14日被美国和英国制裁，据行业媒体报道（2026年6月），他据称持有 Allied Cigar Corporation 57.1%的股份；2026年9月，媒体未报道该部分股份有任何已完成的出售。' AS BINARY)) FROM `habanos_presence` WHERE `country_id` = 'cuba'
