SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme', 'celebrities', 'pairings') AND b.`name` IN ('Arturo Fuente','Padrón','Cohiba','Cohiba USA','Davidoff','Oettinger Davidoff')) = 0 AS sceaux_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` p ON p.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(p.`notes`) AND p.`id` IN ('cuba')) = 0 AS sceaux_pays_a_jour,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'production' AND t.`source_hash` <> SHA1(x.`production`) AND x.`id` = 'cuba') = 0 AS sceau_autre_1,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'rev_detail' AND t.`source_hash` <> SHA1(x.`rev_detail`) AND x.`id` = 'cuba') = 0 AS sceau_autre_2,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `producer_countries` x ON x.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
         WHERE t.`champ` = 'notes' AND t.`source_hash` <> SHA1(x.`notes`) AND x.`id` = 'cuba') = 0 AS sceau_autre_3,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `habanos_presence` x ON x.`country_id` = t.`entite_id` AND t.`entite` = 'habanos_presence'
         WHERE t.`champ` = 'ownership' AND t.`source_hash` <> SHA1(x.`ownership`) AND x.`country_id` = 'cuba') = 0 AS sceau_autre_4,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `habanos_presence` x ON x.`country_id` = t.`entite_id` AND t.`entite` = 'habanos_presence'
         WHERE t.`champ` = 'description' AND t.`source_hash` <> SHA1(x.`description`) AND x.`country_id` = 'cuba') = 0 AS sceau_autre_5,
       (SELECT COUNT(*) FROM `translation_status` t JOIN `habanos_presence` x ON x.`country_id` = t.`entite_id` AND t.`entite` = 'habanos_presence'
         WHERE t.`champ` = 'festival' AND t.`source_hash` <> SHA1(x.`festival`) AND x.`country_id` = 'cuba') = 0 AS sceau_autre_6,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 261') AS journal_non_tronque;
